_SHA256_RE = re.compile(r"[0-9a-f]{64}\Z")
_ATTEMPT_ID_RE = re.compile(r"v2-[1-9][0-9]*-[1-9][0-9]*\Z")
_PUBLICATION_ATTEMPT_ID_RE = re.compile(
    r"v2-presentation-([1-9][0-9]*)-([1-9][0-9]*)\Z"
)
_TRACKED_PUBLICATION_ATTEMPT_ID_RE = re.compile(
    r"v2-tracked-([1-9][0-9]*)-([1-9][0-9]*)\Z"
)


def _normalize_json(value: Any) -> Any:
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, tuple):
        return [_normalize_json(item) for item in value]
    if isinstance(value, list):
        return [_normalize_json(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _normalize_json(item) for key, item in value.items()}
    if value is None or isinstance(value, (str, bool, int, float)):
        return value
    raise V2ContractError(f"non-JSON authority value: {type(value).__name__}")


_OPENAT_AUDIT_CONTEXT: contextvars.ContextVar[dict[str, Any] | None] = (
    contextvars.ContextVar("v2_contract_openat_audit_context", default=None)
)
_OPENAT_AUDIT_LOCK = threading.Lock()
_OPENAT_AUDIT_CAPTURE: dict[str, Any] | None = None
_OPENAT_AUDIT_PURPOSES = (
    "CONTRACT_RUNTIME_OPENAT",
    "FIRST_SCIENTIFIC_OPEN_POST_OPEN_VERIFICATION",
)


def begin_contract_openat_audit_ledger(
    *,
    stage_id: str,
    process_identity: Mapping[str, Any],
    audit_hook_installed_monotonic_ns: int,
) -> None:
    identity = _validate_static_stage_event_process(
        stage_id=stage_id, value=process_identity
    )
    if (
        identity["pid"] != os.getpid()
        or type(audit_hook_installed_monotonic_ns) is not int
        or audit_hook_installed_monotonic_ns < 0
        or _OPENAT_AUDIT_CONTEXT.get() is not None
    ):
        raise V2ContractError("contract openat audit start drift")
    global _OPENAT_AUDIT_CAPTURE
    with _OPENAT_AUDIT_LOCK:
        if _OPENAT_AUDIT_CAPTURE is not None:
            raise V2ContractError("contract openat audit capture already active")
        _OPENAT_AUDIT_CAPTURE = {
            "stage_id": stage_id,
            "process_identity": identity,
            "audit_hook_installed_monotonic_ns": (
                audit_hook_installed_monotonic_ns
            ),
            "next_sequence": 0,
            "rows": [],
            "in_flight_first_scientific_open_event": None,
        }


def current_contract_openat_audit_correlation() -> dict[str, Any] | None:
    value = _OPENAT_AUDIT_CONTEXT.get()
    return None if value is None else copy.deepcopy(value)


def _start_contract_openat_correlation(
    *, relative_path: str, dir_fd: int, flags: int, requested_mode: int,
    audit_purpose: str,
) -> tuple[dict[str, Any] | None, contextvars.Token]:
    global _OPENAT_AUDIT_CAPTURE
    with _OPENAT_AUDIT_LOCK:
        capture = _OPENAT_AUDIT_CAPTURE
        if capture is None or capture["process_identity"]["pid"] != os.getpid():
            return None, _OPENAT_AUDIT_CONTEXT.set(None)
        if _OPENAT_AUDIT_CONTEXT.get() is not None:
            raise V2ContractError("nested contract openat correlation")
        sequence = capture["next_sequence"]
        capture["next_sequence"] += 1
    if (
        type(relative_path) is not str or not relative_path
        or Path(relative_path).is_absolute()
        or os.path.normpath(relative_path) != relative_path
        or ".." in Path(relative_path).parts
        or type(dir_fd) is not int or dir_fd < 0
        or type(flags) is not int or type(requested_mode) is not int
        or audit_purpose not in _OPENAT_AUDIT_PURPOSES
    ):
        raise V2ContractError("contract openat correlation input drift")
    directory_stat = os.fstat(dir_fd)
    directory_path = os.readlink(f"/proc/self/fd/{dir_fd}")
    if (
        not stat.S_ISDIR(directory_stat.st_mode)
        or not Path(directory_path).is_absolute()
        or directory_path.endswith(" (deleted)")
        or str(Path(directory_path)) != directory_path
    ):
        raise V2ContractError("contract openat directory custody drift")
    context = {
        "token": f"v2-openat-{os.getpid()}-{sequence}",
        "sequence": sequence,
        "pid": os.getpid(),
        "stage_id": capture["stage_id"],
        "dir_fd": dir_fd,
        "dir_fd_path": directory_path,
        "dir_fd_stat": _extended_stat_row(directory_stat),
        "relative_path": relative_path,
        "canonical_path": str(Path(directory_path) / relative_path),
        "flags": flags,
        "requested_mode": requested_mode,
        "audit_purpose": audit_purpose,
        "started_monotonic_ns": time.monotonic_ns(),
    }
    return context, _OPENAT_AUDIT_CONTEXT.set(context)


def _finish_contract_openat_correlation(
    *, context: Mapping[str, Any] | None,
    context_token: contextvars.Token,
    descriptor: int | None,
    exception: BaseException | None,
) -> None:
    _OPENAT_AUDIT_CONTEXT.reset(context_token)
    if context is None:
        return
    opened_stat = None
    opened_path = None
    if descriptor is not None:
        opened_stat = _extended_stat_row(os.fstat(descriptor))
        opened_path = os.readlink(f"/proc/self/fd/{descriptor}")
        if (
            opened_path != context["canonical_path"]
            or opened_path.endswith(" (deleted)")
        ):
            raise V2ContractError("contract openat opened-path drift")
    error = None if exception is None else {
        "type": type(exception).__name__, "message": str(exception)
    }
    row = {
        "token": context["token"],
        "sequence": context["sequence"],
        "context": copy.deepcopy(context),
        "completed_monotonic_ns": time.monotonic_ns(),
        "opened": descriptor is not None,
        "opened_fd": descriptor,
        "opened_path": opened_path,
        "opened_stat": opened_stat,
        "exception": error,
    }
    global _OPENAT_AUDIT_CAPTURE
    with _OPENAT_AUDIT_LOCK:
        capture = _OPENAT_AUDIT_CAPTURE
        if capture is None or capture["stage_id"] != context["stage_id"]:
            raise V2ContractError("contract openat capture disappeared")
        capture["rows"].append(row)


def _v2_os_open(
    path: str | bytes | os.PathLike[str] | os.PathLike[bytes],
    flags: int,
    mode: int = 0o777,
    *, dir_fd: int | None = None,
    audit_purpose: str = "CONTRACT_RUNTIME_OPENAT",
) -> int:
    path_value = os.fspath(path)
    if (
        dir_fd is not None
        and isinstance(path_value, bytes)
        and not os.path.isabs(path_value)
    ):
        raise V2ContractError(
            "contract-owned relative openat path must be canonical text"
        )
    if (
        dir_fd is None
        or isinstance(path_value, bytes)
        or os.path.isabs(path_value)
    ):
        return os.open(path, flags, mode, dir_fd=dir_fd)
    context, token = _start_contract_openat_correlation(
        relative_path=path_value, dir_fd=dir_fd,
        flags=flags, requested_mode=mode, audit_purpose=audit_purpose,
    )
    descriptor = None
    error = None
    try:
        descriptor = os.open(path, flags, mode, dir_fd=dir_fd)
        return descriptor
    except BaseException as exc:
        error = exc
        raise
    finally:
        _finish_contract_openat_correlation(
            context=context, context_token=token,
            descriptor=descriptor, exception=error,
        )


def finish_contract_openat_audit_ledger(
    *, stage_id: str, process_identity: Mapping[str, Any],
    audit_stream_completed_monotonic_ns: int,
) -> dict[str, Any]:
    identity = _validate_static_stage_event_process(
        stage_id=stage_id, value=process_identity
    )
    global _OPENAT_AUDIT_CAPTURE
    with _OPENAT_AUDIT_LOCK:
        capture = _OPENAT_AUDIT_CAPTURE
        _OPENAT_AUDIT_CAPTURE = None
    if capture is None or _OPENAT_AUDIT_CONTEXT.get() is not None:
        raise V2ContractError("contract openat audit capture is not complete")
    rows = sorted(
        copy.deepcopy(capture["rows"]), key=lambda row: row["sequence"]
    )
    if (
        capture["stage_id"] != stage_id
        or capture["process_identity"] != identity
        or identity["pid"] != os.getpid()
        or type(audit_stream_completed_monotonic_ns) is not int
        or audit_stream_completed_monotonic_ns
        < capture["audit_hook_installed_monotonic_ns"]
        or [row["sequence"] for row in rows] != list(range(len(rows)))
        or len(rows) != capture["next_sequence"]
        or len({row["token"] for row in rows}) != len(rows)
        or any(
            row["completed_monotonic_ns"] > audit_stream_completed_monotonic_ns
            for row in rows
        )
    ):
        raise V2ContractError("contract openat audit completion drift")
    receipt = attach_self_digest(
        {
            "schema": CONTRACT_OPENAT_AUDIT_LEDGER_SCHEMA,
            "experiment_id": EXPERIMENT_ID,
            "stage_id": stage_id,
            "process_identity": identity,
            "audit_hook_installed_monotonic_ns": capture[
                "audit_hook_installed_monotonic_ns"
            ],
            "audit_stream_completed_monotonic_ns": (
                audit_stream_completed_monotonic_ns
            ),
            "rows": rows,
            "row_count": len(rows),
            "in_flight_first_scientific_open_event": copy.deepcopy(
                capture["in_flight_first_scientific_open_event"]
            ),
            "tokens_unique_and_consumed_once": True,
            "open_failure_count": sum(not row["opened"] for row in rows),
            "pass": all(row["opened"] for row in rows),
        }
    )
    validate_contract_openat_audit_ledger(receipt)
    return receipt


def canonical_json_bytes(value: Any) -> bytes:
    try:
        return json.dumps(
            _normalize_json(value), sort_keys=True, separators=(",", ":"),
            ensure_ascii=False, allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise V2ContractError("value is not canonical JSON") from exc


def canonical_json_sha256(value: Any) -> str:
    return hashlib.sha256(canonical_json_bytes(value)).hexdigest()


def _has_exact_keys(value: Any, expected_keys: Sequence[str]) -> bool:
    """JSON object schemas are exact but never depend on key order."""

    expected = tuple(expected_keys)
    return (
        type(value) is dict
        and len(value) == len(expected)
        and set(value) == set(expected)
    )


def attach_self_digest(value: Mapping[str, Any]) -> dict[str, Any]:
    if type(value) is not dict:
        raise V2ContractError("self-digested value must be a plain dict")
    result = copy.deepcopy(value)
    result.pop("content_digest", None)
    result["content_digest"] = canonical_json_sha256(result)
    return result


def validate_self_digest(value: Mapping[str, Any]) -> dict[str, Any]:
    if type(value) is not dict:
        raise V2ContractError("self-digested value must be a plain dict")
    result = copy.deepcopy(value)
    digest = result.pop("content_digest", None)
    if not isinstance(digest, str) or not _SHA256_RE.fullmatch(digest):
        raise V2ContractError("content_digest malformed")
    if canonical_json_sha256(result) != digest:
        raise V2ContractError("content_digest mismatch")
    return copy.deepcopy(value)


def publication_attempt_relative_root(
    publication_attempt_number: int, publication_attempt_id: str
) -> str:
    if (
        type(publication_attempt_number) is not int
        or publication_attempt_number < 1
        or not isinstance(publication_attempt_id, str)
    ):
        raise V2ContractError("publication-attempt identity drift")
    matched = _PUBLICATION_ATTEMPT_ID_RE.fullmatch(publication_attempt_id)
    if matched is None or int(matched.group(1)) != publication_attempt_number:
        raise V2ContractError("publication-attempt id/number drift")
    return f"presentation_attempts/{publication_attempt_id}"


