def expected_phase1_supervisor_argv(attempt_id: str) -> list[str]:
    if not isinstance(attempt_id, str) or not _ATTEMPT_ID_RE.fullmatch(
        attempt_id
    ):
        raise V2ContractError("Phase-1 supervisor attempt id drift")
    return [
        str(PYTHON_EXECUTABLE), "-E", "-s", "-u", str(EVALUATOR_PATH),
        PHASE1_SUPERVISOR_MODE, "--attempt-id", attempt_id,
    ]


def expected_internal_argv(
    mode: str,
    attempt_root: str | Path,
    *,
    publication_attempt_number: int | None = None,
    publication_attempt_id: str | None = None,
    presentation_retry_authority_content_digest: str | None = None,
    supervisor_observation_content_digest: str | None = None,
) -> list[str]:
    if mode not in INTERNAL_MODES:
        raise V2ContractError("unknown internal V2 mode")
    root = Path(attempt_root).absolute()
    expected_parent = OUTPUT_ROOT.parent
    if root.parent != expected_parent or not root.name.startswith(
        f".{OUTPUT_ROOT.name}.attempt-"
    ):
        raise V2ContractError("V2 attempt-root grammar drift")
    result = [
        str(PYTHON_EXECUTABLE), "-E", "-s", "-u", str(EVALUATOR_PATH),
        mode, "--attempt-root", str(root),
    ]
    if mode == TERMINAL_PUBLICATION_SUPERVISOR_MODE:
        raise V2ContractError(
            "terminal publication supervisor requires exact boundary argv"
        )
    if mode == PHASE1_TERMINAL_CUSTODY_MODE:
        if (
            not isinstance(supervisor_observation_content_digest, str)
            or not _SHA256_RE.fullmatch(
                supervisor_observation_content_digest
            )
            or publication_attempt_number is not None
            or publication_attempt_id is not None
            or presentation_retry_authority_content_digest is not None
        ):
            raise V2ContractError(
                "Phase-1 terminal attestor lacks supervisor observation"
            )
        result.extend(
            (
                "--supervisor-observation-content-digest",
                supervisor_observation_content_digest,
            )
        )
        return result
    if supervisor_observation_content_digest is not None:
        raise V2ContractError(
            "non-attestor argv has supervisor-observation digest"
        )
    if mode != PHASE3_PUBLISHER_MODE:
        if (
            publication_attempt_number is not None
            or publication_attempt_id is not None
            or presentation_retry_authority_content_digest is not None
        ):
            raise V2ContractError("non-Phase-3 argv has publication identity")
        return result
    if publication_attempt_number is None or publication_attempt_id is None:
        raise V2ContractError("Phase-3 argv lacks publication-attempt identity")
    publication_attempt_relative_root(
        publication_attempt_number, publication_attempt_id
    )
    if publication_attempt_number == 1:
        if presentation_retry_authority_content_digest is not None:
            raise V2ContractError("initial Phase 3 has retry authority")
    elif (
        not isinstance(presentation_retry_authority_content_digest, str)
        or not _SHA256_RE.fullmatch(
            presentation_retry_authority_content_digest
        )
    ):
        raise V2ContractError("retry Phase 3 lacks authority digest")
    result.extend(
        (
            "--publication-attempt-number",
            str(publication_attempt_number),
            "--publication-attempt-id",
            publication_attempt_id,
        )
    )
    if presentation_retry_authority_content_digest is not None:
        result.extend(
            (
                "--presentation-retry-authority-content-digest",
                presentation_retry_authority_content_digest,
            )
        )
    return result


def expected_terminal_publication_supervisor_argv(
    attempt_root: str | Path,
    *,
    resume_boundary: str,
    publication_attempt_number: int,
    publication_attempt_id: str,
    tracked_attempt_number: int,
    tracked_attempt_id: str,
    phase_1_custody_content_digest: str,
    phase_2_custody_content_digest: str | None = None,
    phase_3_custody_content_digest: str | None = None,
    presentation_retry_authority_content_digest: str | None = None,
    tracked_retry_authority_content_digest: str | None = None,
) -> list[str]:
    root = Path(attempt_root).absolute()
    expected_internal_argv(PHASE2_VALIDATOR_MODE, root)
    if resume_boundary not in TERMINAL_PUBLICATION_RESUME_BOUNDARIES:
        raise V2ContractError("terminal supervisor resume boundary drift")
    publication_attempt_relative_root(
        publication_attempt_number, publication_attempt_id
    )
    tracked_publication_attempt_relative_root(
        tracked_attempt_number, tracked_attempt_id
    )
    digest_values = {
        "phase_1": phase_1_custody_content_digest,
        "phase_2": phase_2_custody_content_digest,
        "phase_3": phase_3_custody_content_digest,
        "presentation_retry": presentation_retry_authority_content_digest,
        "tracked_retry": tracked_retry_authority_content_digest,
    }
    if not isinstance(phase_1_custody_content_digest, str) or not (
        _SHA256_RE.fullmatch(phase_1_custody_content_digest)
    ):
        raise V2ContractError("terminal supervisor lacks Phase-1 custody")
    for key, value in digest_values.items():
        if value is not None and (
            not isinstance(value, str) or not _SHA256_RE.fullmatch(value)
        ):
            raise V2ContractError(
                f"terminal supervisor {key} digest drift"
            )
    requires_phase2 = resume_boundary != "AFTER_PHASE_1"
    requires_phase3 = resume_boundary in (
        "AFTER_SUCCESSFUL_PHASE_3",
        "GIT_ONLY_FROM_PRESERVED_STAGING",
        "POSTCOMMIT_OBSERVATION_ONLY",
    )
    if (phase_2_custody_content_digest is not None) is not requires_phase2:
        raise V2ContractError("terminal supervisor Phase-2 resume drift")
    if (phase_3_custody_content_digest is not None) is not requires_phase3:
        raise V2ContractError("terminal supervisor Phase-3 resume drift")
    if publication_attempt_number == 1:
        if presentation_retry_authority_content_digest is not None:
            raise V2ContractError("initial presentation has retry digest")
    elif presentation_retry_authority_content_digest is None:
        raise V2ContractError("presentation retry lacks authority digest")
    if tracked_attempt_number == 1:
        if tracked_retry_authority_content_digest is not None:
            raise V2ContractError("initial tracked attempt has retry digest")
    elif tracked_retry_authority_content_digest is None:
        raise V2ContractError("tracked retry lacks authority digest")
    if (
        resume_boundary == "GIT_ONLY_FROM_PRESERVED_STAGING"
        and tracked_attempt_number < 2
    ):
        raise V2ContractError("Git-only resume lacks tracked failure chain")
    if (
        resume_boundary == "POSTCOMMIT_OBSERVATION_ONLY"
        and tracked_attempt_number < 2
    ):
        raise V2ContractError(
            "postcommit-observation resume lacks tracked failure chain"
        )
    if resume_boundary == "AFTER_PHASE_1" and (
        publication_attempt_number != 1
        or tracked_attempt_number != 1
    ):
        raise V2ContractError("initial terminal sequence attempt drift")
    if (
        resume_boundary == "AFTER_PHASE_2_VALIDATION"
        and tracked_attempt_number != 1
    ):
        raise V2ContractError("presentation-only resume tracked attempt drift")
    result = [
        str(PYTHON_EXECUTABLE), "-E", "-s", "-u", str(EVALUATOR_PATH),
        TERMINAL_PUBLICATION_SUPERVISOR_MODE,
        "--attempt-root", str(root),
        "--resume-boundary", resume_boundary,
        "--publication-attempt-number", str(publication_attempt_number),
        "--publication-attempt-id", publication_attempt_id,
        "--tracked-attempt-number", str(tracked_attempt_number),
        "--tracked-attempt-id", tracked_attempt_id,
        "--phase-1-custody-content-digest",
        phase_1_custody_content_digest,
    ]
    for option, value in (
        ("--phase-2-custody-content-digest", phase_2_custody_content_digest),
        ("--phase-3-custody-content-digest", phase_3_custody_content_digest),
        (
            "--presentation-retry-authority-content-digest",
            presentation_retry_authority_content_digest,
        ),
        ("--tracked-retry-authority-content-digest", (
            tracked_retry_authority_content_digest
        )),
    ):
        if value is not None:
            result.extend((option, value))
    return result


def expected_pre_root_phase1_failure_custody_argv(
    supervisor_observation_content_digest: str,
) -> list[str]:
    if (
        not isinstance(supervisor_observation_content_digest, str)
        or not _SHA256_RE.fullmatch(
            supervisor_observation_content_digest
        )
    ):
        raise V2ContractError(
            "pre-root attestor lacks supervisor-observation digest"
        )
    return [
        str(PYTHON_EXECUTABLE), "-E", "-s", "-u", str(EVALUATOR_PATH),
        PRE_ROOT_PHASE1_FAILURE_CUSTODY_MODE,
        "--custody-path", str(PRE_ROOT_FAILURE_CUSTODY_PATH),
        "--supervisor-observation-content-digest",
        supervisor_observation_content_digest,
    ]


def expected_phase1_worker_argv(
    mode: str,
    attempt_root: str | Path,
    *,
    state_index: int | None = None,
    source_id: str | None = None,
    ablation: str | None = None,
) -> list[str]:
    root = Path(attempt_root).absolute()
    expected_internal_argv(PHASE2_VALIDATOR_MODE, root)
    if mode == PHASE1_CONTEXT_STATE_WORKER_MODE:
        if (
            type(state_index) is not int
            or state_index < 0
            or state_index >= 48
            or source_id is not None
            or ablation is not None
        ):
            raise V2ContractError("context-state worker identity drift")
        return [
            str(CPU_WORKER_PYTHON_EXECUTABLE), "-E", "-s", "-u",
            str(EVALUATOR_PATH), mode, "--attempt-root", str(root),
            "--state-index", str(state_index),
        ]
    if mode == PHASE1_PREDICTION_SOURCE_WORKER_MODE:
        if state_index is not None or source_id not in (
            "P1_PROPRIO_ONE_STEP", "PR_PROPRIO_ROLLOUT"
        ):
            raise V2ContractError("prediction worker source drift")
        if ablation is not None and (
            source_id != "PR_PROPRIO_ROLLOUT"
            or ablation not in V1.STAGE_C_ABLATION_INPUTS
        ):
            raise V2ContractError("prediction worker ablation drift")
        result = [
            str(PYTHON_EXECUTABLE), "-E", "-s", "-u",
            str(EVALUATOR_PATH), mode, "--attempt-root", str(root),
            "--source-id", source_id,
        ]
        if ablation is not None:
            result.extend(("--ablation", ablation))
        return result
    raise V2ContractError("unknown Phase-1 worker mode")


def runtime_path(key: str, attempt_root: str | Path) -> Path:
    if key not in RUNTIME_PATHS:
        raise V2ContractError("unknown V2 runtime path")
    root = Path(attempt_root).absolute()
    expected_internal_argv(PHASE2_VALIDATOR_MODE, root)
    return root / RUNTIME_PATHS[key]


def terminal_publication_supervisor_failure_custody_path(
    attempt_id: str,
) -> Path:
    if not isinstance(attempt_id, str) or not _ATTEMPT_ID_RE.fullmatch(
        attempt_id
    ):
        raise V2ContractError("terminal supervisor failure attempt id drift")
    return OUTPUT_ROOT.parent / (
        f".{OUTPUT_ROOT.name}.attempt-{attempt_id}."
        "terminal_publication_supervisor_failure_custody.json"
    )


def rooted_phase1_supervisor_failure_custody_path(
    attempt_id: str,
) -> Path:
    if not isinstance(attempt_id, str) or not _ATTEMPT_ID_RE.fullmatch(
        attempt_id
    ):
        raise V2ContractError("rooted Phase-1 failure attempt id drift")
    return OUTPUT_ROOT.parent / (
        f".{OUTPUT_ROOT.name}.attempt-{attempt_id}."
        "rooted_phase_1_supervisor_failure_custody.json"
    )


def raw_phase3_failure_preservation_relative_path(
    publication_attempt_number: int,
    publication_attempt_id: str,
) -> str:
    publication_attempt_relative_root(
        publication_attempt_number, publication_attempt_id
    )
    return (
        "receipts/raw_phase_3_failure_preservation/"
        f"{publication_attempt_id}.json"
    )


def raw_phase3_supervisor_failure_custody_relative_path(
    publication_attempt_number: int,
    publication_attempt_id: str,
) -> str:
    publication_attempt_relative_root(
        publication_attempt_number, publication_attempt_id
    )
    return (
        "receipts/raw_phase_3_supervisor_failures/"
        f"{publication_attempt_id}.json"
    )


def _build_presentation_retry_authority_from_live_observations(
    *, prior_validated_payload_content_digest: str,
    prior_validation_receipt_content_digest: str,
    prior_failed_attempt_custodies: Sequence[Mapping[str, Any]],
    prior_failure_preservation_receipts: Sequence[Mapping[str, Any]],
    live_prior_failure_namespace_inventories: Sequence[
        Mapping[str, Any]
    ],
    retry_observer_process_identity: Mapping[str, Any],
    retry_observation_started_monotonic_ns: int,
    retry_authority_built_monotonic_ns: int,
    attempt_root_fd_custody_content_digest: str,
    reopened_attempt_root_fd_custody_content_digest: str,
    authorized_publication_attempt: int,
    reason: str,
) -> dict[str, Any]:
    if (
        not isinstance(prior_validated_payload_content_digest, str)
        or not _SHA256_RE.fullmatch(prior_validated_payload_content_digest)
        or not isinstance(prior_validation_receipt_content_digest, str)
        or not _SHA256_RE.fullmatch(
            prior_validation_receipt_content_digest
        )
        or isinstance(prior_failed_attempt_custodies, (str, bytes))
        or not isinstance(prior_failed_attempt_custodies, Sequence)
        or isinstance(prior_failure_preservation_receipts, (str, bytes))
        or not isinstance(prior_failure_preservation_receipts, Sequence)
        or isinstance(
            live_prior_failure_namespace_inventories, (str, bytes)
        )
        or not isinstance(
            live_prior_failure_namespace_inventories, Sequence
        )
        or not isinstance(
            attempt_root_fd_custody_content_digest, str
        )
        or not _SHA256_RE.fullmatch(
            attempt_root_fd_custody_content_digest
        )
        or not isinstance(
            reopened_attempt_root_fd_custody_content_digest, str
        )
        or not _SHA256_RE.fullmatch(
            reopened_attempt_root_fd_custody_content_digest
        )
        or type(retry_observation_started_monotonic_ns) is not int
        or retry_observation_started_monotonic_ns < 0
        or type(retry_authority_built_monotonic_ns) is not int
        or retry_authority_built_monotonic_ns
        < retry_observation_started_monotonic_ns
        or type(authorized_publication_attempt) is not int
        or authorized_publication_attempt < 2
        or type(reason) is not str
        or not reason.strip()
    ):
        raise V2ContractError("presentation retry authority drift")
    failures = []
    for row in prior_failed_attempt_custodies:
        if type(row) is not dict:
            raise V2ContractError(
                "presentation retry failure custody malformed"
            )
        if row.get("schema") == RAW_PHASE3_SUPERVISOR_FAILURE_CUSTODY_SCHEMA:
            failures.append(
                validate_raw_phase3_supervisor_failure_custody(row)
            )
        else:
            failures.append(
                validate_presentation_attempt_failure_custody(row)
            )
    preservations = []
    for row in prior_failure_preservation_receipts:
        if type(row) is not dict:
            raise V2ContractError(
                "presentation retry preservation receipt malformed"
            )
        if row.get("schema") == RAW_PHASE3_FAILURE_PRESERVATION_RECEIPT_SCHEMA:
            preservations.append(
                validate_raw_phase3_failure_preservation_receipt(row)
            )
        else:
            preservations.append(
                validate_presentation_failure_preservation_receipt(row)
            )
    live_inventories = []
    for row in live_prior_failure_namespace_inventories:
        if type(row) is not dict:
            raise V2ContractError(
                "presentation retry live inventory malformed"
            )
        if row.get("schema") == RAW_PHASE3_NAMESPACE_INVENTORY_SCHEMA:
            live_inventories.append(
                validate_raw_phase3_namespace_inventory(row)
            )
        else:
            live_inventories.append(
                validate_presentation_attempt_namespace_inventory(row)
            )
    observer = _validate_process_identity(retry_observer_process_identity)
    if (
        len(failures) != authorized_publication_attempt - 1
        or len(preservations) != len(failures)
        or len(live_inventories) != len(failures)
        or [row["publication_attempt_number"] for row in failures]
        != list(range(1, authorized_publication_attempt))
        or len({row["publication_attempt_id"] for row in failures})
        != len(failures)
    ):
        raise V2ContractError("presentation retry failure chain drift")
    for failure_index, (failure, preservation, live) in enumerate(zip(
        failures, preservations, live_inventories
    )):
        raw = (
            failure["schema"]
            == RAW_PHASE3_SUPERVISOR_FAILURE_CUSTODY_SCHEMA
        )
        if raw:
            if (
                preservation["schema"]
                != RAW_PHASE3_FAILURE_PRESERVATION_RECEIPT_SCHEMA
                or live["schema"] != RAW_PHASE3_NAMESPACE_INVENTORY_SCHEMA
            ):
                raise V2ContractError(
                    "raw Phase-3 retry receipt-kind drift"
                )
            frozen = preservation["preserved_inventory"]
            observation = failure["failure_observation"]
            phase2 = failure["phase_2_custody"]
            phase2_exit = phase2[
                "terminal_publication_child_exit_observation"
            ]
            phase1 = phase2_exit[
                "terminal_publication_child_handoff_memfd_custody"
            ]["payload"]["phase_1_custody"]
            if (
                phase1["produced_artifact_binding"]["content_digest"]
                != prior_validated_payload_content_digest
                or phase2["produced_artifact_binding"]["content_digest"]
                != prior_validation_receipt_content_digest
                or failure["known_pre_popen_namespace_absent"] is not True
                or failure[
                    "explicit_new_presentation_attempt_authority_required"
                ] is not True
                or failure["partial_runtime_artifact_bindings"] != []
                or failure["partial_runtime_artifact_paths"] != []
                or observation["popen_succeeded"] is not False
                or observation["child_process_identity"] is not None
                or observation["spawned_pid"] is not None
                or observation["spawned_process_group_id"] is not None
                or observation["cleanup_complete"] is not True
                or preservation["preservation_complete"] is not True
                or preservation[
                    "explicit_new_presentation_attempt_authority_possible"
                ] is not True
                or frozen["namespace_state"] != "ABSENT"
                or frozen["leaf_rows"] != []
                or live["inventory_stage"]
                != "RAW_FAILURE_PRESERVED_READ_ONLY"
                or live["namespace_state"] != "ABSENT"
                or live["leaf_rows"] != []
                or live["content_digest"] == frozen["content_digest"]
            ):
                raise V2ContractError(
                    "raw Phase-3 clean retry authority drift"
                )
            failure_root = failure["attempt_root"]
            nested_retry = observation["presentation_retry_authority"]
        else:
            if (
                preservation["schema"]
                != PRESENTATION_FAILURE_PRESERVATION_RECEIPT_SCHEMA
                or live["schema"]
                != PRESENTATION_ATTEMPT_NAMESPACE_INVENTORY_SCHEMA
                or failure["immutable_payload_content_digest"]
                != prior_validated_payload_content_digest
                or failure["independent_validation_content_digest"]
                != prior_validation_receipt_content_digest
                or failure["presentation_retry_eligible"] is not True
                or failure[
                    "unknown_phase_3_start_or_cleanup_state_blocks_retry"
                ] is not False
                or live["inventory_stage"]
                != "FAILED_NAMESPACE_PRESERVED_READ_ONLY"
            ):
                raise V2ContractError(
                    "presentation retry canonical failure drift"
                )
            frozen = preservation["preserved_read_only_inventory"]
            failure_root = failure[
                "failed_phase_3_exit_observation"
            ]["attempt_root"]
            nested_retry = failure[
                "failed_phase_3_exit_observation"
            ]["presentation_retry_authority"]
        failure_number = failure["publication_attempt_number"]
        if failure_number == 1:
            if nested_retry is not None:
                raise V2ContractError(
                    "initial failed presentation carries retry authority"
                )
        else:
            nested_retry = validate_presentation_retry_authority(
                nested_retry, expected_attempt=failure_number
            )
            if (
                nested_retry["prior_validated_payload_content_digest"]
                != prior_validated_payload_content_digest
                or nested_retry[
                    "prior_validation_receipt_content_digest"
                ] != prior_validation_receipt_content_digest
                or nested_retry["prior_failed_attempt_content_digests"]
                != [
                    row["content_digest"]
                    for row in failures[:failure_index]
                ]
            ):
                raise V2ContractError(
                    "presentation retry nested failure chain drift"
                )
        if (
            preservation["failure_custody_content_digest"]
            != failure["content_digest"]
            or preservation["publication_attempt_number"]
            != failure["publication_attempt_number"]
            or preservation["publication_attempt_id"]
            != failure["publication_attempt_id"]
            or live["publication_attempt_number"]
            != failure["publication_attempt_number"]
            or live["publication_attempt_id"]
            != failure["publication_attempt_id"]
            or live["attempt_root"] != failure_root
            or live["attempt_root"] != frozen["attempt_root"]
            or live["observer_process_identity"] != observer
            or live["observation_started_monotonic_ns"]
            <= preservation["preservation_completed_monotonic_ns"]
            or live["observation_started_monotonic_ns"]
            < retry_observation_started_monotonic_ns
            or live["observation_completed_monotonic_ns"]
            > retry_authority_built_monotonic_ns
            or live["attempt_root_fd_custody_content_digest"]
            != attempt_root_fd_custody_content_digest
            or live[
                "reopened_attempt_root_fd_custody_content_digest"
            ] != reopened_attempt_root_fd_custody_content_digest
            or live["namespace_inventory_sha256"]
            != frozen["namespace_inventory_sha256"]
            or live["leaf_rows"] != frozen["leaf_rows"]
            or live["directory_stat"] != frozen["directory_stat"]
        ):
            raise V2ContractError(
                "presentation retry preserved namespace drift"
            )
    failure_bindings = []
    for failure in failures:
        failure_bytes = canonical_json_bytes(failure) + b"\n"
        failure_bindings.append(
            build_artifact_binding(
                path=failure["failure_custody_relative_path"],
                sha256=hashlib.sha256(failure_bytes).hexdigest(),
                bytes_count=len(failure_bytes),
                content_digest=failure["content_digest"],
                rows=None,
            )
        )
    return attach_self_digest(
        {
            "schema": PRESENTATION_RETRY_AUTHORITY_SCHEMA,
            "prior_validated_payload_content_digest": (
                prior_validated_payload_content_digest
            ),
            "prior_validation_receipt_content_digest": (
                prior_validation_receipt_content_digest
            ),
            "prior_failed_attempt_custodies": failures,
            "prior_failure_preservation_receipts": preservations,
            "live_prior_failure_namespace_inventories": live_inventories,
            "retry_observer_process_identity": observer,
            "retry_observation_started_monotonic_ns": (
                retry_observation_started_monotonic_ns
            ),
            "retry_authority_built_monotonic_ns": (
                retry_authority_built_monotonic_ns
            ),
            "attempt_root_fd_custody_content_digest": (
                attempt_root_fd_custody_content_digest
            ),
            "reopened_attempt_root_fd_custody_content_digest": (
                reopened_attempt_root_fd_custody_content_digest
            ),
            "prior_failed_attempt_content_digests": [
                row["content_digest"] for row in failures
            ],
            "prior_failed_attempt_custody_bindings": failure_bindings,
            "prior_publication_attempts": len(failures),
            "authorized_publication_attempt": authorized_publication_attempt,
            "reason": reason.strip(),
            "presentation_only": True,
            "scientific_attempt_authorized": False,
            "retraining_or_inference_authorized": False,
            "metric_recomputation_authorized": False,
            "exact_validated_payload_reuse_required": True,
            "all_prior_attempt_namespaces_preserved_read_only": True,
            "all_prior_attempt_namespaces_live_reverified": True,
            "live_observations_are_not_historical_receipt_aliases": True,
            "all_prior_attempt_products_ineligible_for_publication": True,
            "automatic_retry": False,
        }
    )


def observe_and_build_presentation_retry_authority(
    *,
    prior_validated_payload_content_digest: str,
    prior_validation_receipt_content_digest: str,
    prior_failed_attempt_custodies: Sequence[Mapping[str, Any]],
    prior_failure_preservation_receipts: Sequence[Mapping[str, Any]],
    attempt_root_fd_custody: Mapping[str, Any],
    reopened_attempt_root_fd_custody: Mapping[str, Any],
    root_fd: int,
    observer_process_identity: Mapping[str, Any],
    authorized_publication_attempt: int,
    reason: str,
) -> dict[str, Any]:
    """Re-walk every preserved failure namespace before authorizing retry."""

    observation_started = time.monotonic_ns()
    historical = _validate_live_attempt_root_access(
        attempt_root_fd_custody=attempt_root_fd_custody,
        root_fd=root_fd,
        reopened_attempt_root_fd_custody=(
            reopened_attempt_root_fd_custody
        ),
    )
    observer = _require_exact_live_process_identity(
        observer_process_identity
    )
    if reopened_attempt_root_fd_custody.get("schema") == (
        TERMINAL_PUBLICATION_SUPERVISOR_ROOT_REOPEN_CUSTODY_SCHEMA
    ):
        reopen = validate_terminal_publication_supervisor_root_reopen_custody(
            reopened_attempt_root_fd_custody,
            attempt_root_fd_custody=historical,
            reverify_live=False,
        )
    else:
        reopen = validate_reopened_attempt_root_fd_custody(
            reopened_attempt_root_fd_custody,
            attempt_root_fd_custody=historical,
            reverify_live=False,
        )
    if (
        isinstance(prior_failed_attempt_custodies, (str, bytes))
        or not isinstance(prior_failed_attempt_custodies, Sequence)
        or isinstance(prior_failure_preservation_receipts, (str, bytes))
        or not isinstance(prior_failure_preservation_receipts, Sequence)
        or len(prior_failed_attempt_custodies)
        != len(prior_failure_preservation_receipts)
    ):
        raise V2ContractError("presentation retry custody chain malformed")
    failures = []
    preservations = []
    live_inventories = []
    for failure_value, preservation_value in zip(
        prior_failed_attempt_custodies,
        prior_failure_preservation_receipts,
    ):
        if type(failure_value) is not dict or type(
            preservation_value
        ) is not dict:
            raise V2ContractError(
                "presentation retry custody chain row malformed"
            )
        raw = failure_value.get("schema") == (
            RAW_PHASE3_SUPERVISOR_FAILURE_CUSTODY_SCHEMA
        )
        if raw:
            failure = validate_raw_phase3_supervisor_failure_custody(
                failure_value
            )
            preservation = validate_raw_phase3_failure_preservation_receipt(
                preservation_value
            )
            failure_payload = read_v2_attempt_bytes_no_follow(
                attempt_root_fd_custody=historical,
                reopened_attempt_root_fd_custody=reopen,
                root_fd=root_fd,
                relative_path=failure["failure_custody_relative_path"],
                expected_binding=preservation["failure_custody_binding"],
            )
            loaded_failure = _canonical_mapping_from_bytes(
                failure_payload,
                field="raw Phase-3 persisted failure custody",
                allow_empty=False,
            )
            preservation_payload = canonical_json_bytes(preservation) + b"\n"
            preservation_binding = build_artifact_binding(
                path=preservation["preservation_receipt_relative_path"],
                sha256=hashlib.sha256(preservation_payload).hexdigest(),
                bytes_count=len(preservation_payload),
                content_digest=preservation["content_digest"], rows=None,
            )
            loaded_preservation_bytes = read_v2_attempt_bytes_no_follow(
                attempt_root_fd_custody=historical,
                reopened_attempt_root_fd_custody=reopen,
                root_fd=root_fd,
                relative_path=preservation[
                    "preservation_receipt_relative_path"
                ],
                expected_binding=preservation_binding,
            )
            loaded_preservation = _canonical_mapping_from_bytes(
                loaded_preservation_bytes,
                field="raw Phase-3 persisted preservation receipt",
                allow_empty=False,
            )
            if (
                loaded_failure is None
                or validate_raw_phase3_supervisor_failure_custody(
                    loaded_failure
                ) != failure
                or loaded_preservation is None
                or validate_raw_phase3_failure_preservation_receipt(
                    loaded_preservation
                ) != preservation
            ):
                raise V2ContractError(
                    "raw Phase-3 live persisted retry custody drift"
                )
            live = observe_raw_phase3_namespace_inventory(
                attempt_root_fd_custody=historical,
                reopened_attempt_root_fd_custody=reopen,
                root_fd=root_fd,
                observer_process_identity=observer,
                publication_attempt_number=failure[
                    "publication_attempt_number"
                ],
                publication_attempt_id=failure[
                    "publication_attempt_id"
                ],
                inventory_stage="RAW_FAILURE_PRESERVED_READ_ONLY",
            )
        else:
            failure = validate_presentation_attempt_failure_custody(
                failure_value
            )
            preservation = validate_presentation_failure_preservation_receipt(
                preservation_value
            )
            live = observe_presentation_attempt_namespace_inventory(
                attempt_root_fd_custody=historical,
                reopened_attempt_root_fd_custody=reopen,
                root_fd=root_fd,
                observer_process_identity=observer,
                publication_attempt_number=failure[
                    "publication_attempt_number"
                ],
                publication_attempt_id=failure[
                    "publication_attempt_id"
                ],
                inventory_stage="FAILED_NAMESPACE_PRESERVED_READ_ONLY",
            )
        failures.append(failure)
        preservations.append(preservation)
        live_inventories.append(live)
    built = time.monotonic_ns()
    return _build_presentation_retry_authority_from_live_observations(
        prior_validated_payload_content_digest=(
            prior_validated_payload_content_digest
        ),
        prior_validation_receipt_content_digest=(
            prior_validation_receipt_content_digest
        ),
        prior_failed_attempt_custodies=failures,
        prior_failure_preservation_receipts=preservations,
        live_prior_failure_namespace_inventories=live_inventories,
        retry_observer_process_identity=observer,
        retry_observation_started_monotonic_ns=observation_started,
        retry_authority_built_monotonic_ns=built,
        attempt_root_fd_custody_content_digest=historical[
            "content_digest"
        ],
        reopened_attempt_root_fd_custody_content_digest=reopen[
            "content_digest"
        ],
        authorized_publication_attempt=authorized_publication_attempt,
        reason=reason,
    )


def validate_presentation_retry_authority(
    value: Mapping[str, Any], *, expected_attempt: int
) -> dict[str, Any]:
    validate_self_digest(value)
    rebuilt = _build_presentation_retry_authority_from_live_observations(
        prior_validated_payload_content_digest=value.get(
            "prior_validated_payload_content_digest"
        ),
        prior_validation_receipt_content_digest=value.get(
            "prior_validation_receipt_content_digest"
        ),
        prior_failed_attempt_custodies=value.get(
            "prior_failed_attempt_custodies"
        ),
        prior_failure_preservation_receipts=value.get(
            "prior_failure_preservation_receipts"
        ),
        live_prior_failure_namespace_inventories=value.get(
            "live_prior_failure_namespace_inventories"
        ),
        retry_observer_process_identity=value.get(
            "retry_observer_process_identity"
        ),
        retry_observation_started_monotonic_ns=value.get(
            "retry_observation_started_monotonic_ns"
        ),
        retry_authority_built_monotonic_ns=value.get(
            "retry_authority_built_monotonic_ns"
        ),
        attempt_root_fd_custody_content_digest=value.get(
            "attempt_root_fd_custody_content_digest"
        ),
        reopened_attempt_root_fd_custody_content_digest=value.get(
            "reopened_attempt_root_fd_custody_content_digest"
        ),
        authorized_publication_attempt=value.get(
            "authorized_publication_attempt"
        ),
        reason=value.get("reason"),
    )
    if value != rebuilt or value["authorized_publication_attempt"] != expected_attempt:
        raise V2ContractError("presentation retry authority mismatch")
    return copy.deepcopy(value)


def presentation_retry_authority_bytes(
    value: Mapping[str, Any], *, expected_attempt: int
) -> bytes:
    validated = validate_presentation_retry_authority(
        value, expected_attempt=expected_attempt
    )
    return canonical_json_bytes(validated) + b"\n"


def build_attempt_accounting(
    state: str,
    *,
    publication_attempt_number: int = 1,
    presentation_retry_authority: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if state not in ATTEMPT_STATES:
        raise V2ContractError("unknown V2 attempt state")
    if type(publication_attempt_number) is not int or publication_attempt_number < 1:
        raise V2ContractError("publication attempt number drift")
    publication_state = state in {
        "PUBLICATION_STARTED", "PUBLICATION_COMPLETE", "FAILED_PUBLICATION"
    }
    if publication_attempt_number == 1:
        if presentation_retry_authority is not None:
            raise V2ContractError("initial publication forbids retry authority")
        retry = None
    else:
        if not publication_state or presentation_retry_authority is None:
            raise V2ContractError("later publication requires explicit authority")
        retry = validate_presentation_retry_authority(
            presentation_retry_authority,
            expected_attempt=publication_attempt_number,
        )
    # The immutable amendment records startup 1 as consumed before this
    # corrected execution is accepted.  REGISTERED is the supervisor's
    # prelaunch state for startup 2; every later state is after the exact
    # unchanged public execute argv has consumed startup 2.
    technical = 1 if state == "REGISTERED" else 2
    scientific_unknown = state == "UNKNOWN_NO_RETRY"
    scientific = (
        None
        if scientific_unknown
        else int(state in {
            "SCIENTIFIC_STARTED", "IMMUTABLE_PAYLOAD_FROZEN",
            "SCIENCE_EXECUTED_PENDING_VALIDATION",
            "SCIENCE_VALIDATED", "PUBLICATION_STARTED",
            "SCIENTIFIC_ATTEMPT_COMPLETE",
            "PUBLICATION_COMPLETE", "FAILED_SCIENCE",
            "FAILED_VALIDATION", "FAILED_PUBLICATION",
        })
    )
    publication = publication_attempt_number if publication_state else 0
    science_complete = state in {
        "SCIENCE_VALIDATED", "PUBLICATION_STARTED", "PUBLICATION_COMPLETE",
        "SCIENTIFIC_ATTEMPT_COMPLETE",
        "FAILED_PUBLICATION",
    }
    return attach_self_digest(
        {
            "schema": ATTEMPT_ACCOUNTING_SCHEMA,
            "state": state,
            "technical_startup_attempt": {
                "authorized": 2, "consumed": technical,
                "remaining": 2 - technical,
                "prior_failed_startup_attempts_consumed": 1,
                "prior_failed_startup_attempt_id": (
                    FAILED_TECHNICAL_STARTUP_ATTEMPT_ID
                ),
                "current_corrected_startup_attempt_number": 2,
                "current_corrected_startup_attempt_id": (
                    CORRECTED_TECHNICAL_STARTUP_ATTEMPT_ID
                ),
                "technical_correction_amendment_path": str(
                    TRACKED_TECHNICAL_CORRECTION_AMENDMENT_PATH
                ),
                "technical_correction_amendment_sha256": (
                    TECHNICAL_CORRECTION_AMENDMENT_SHA256
                ),
                "technical_correction_amendment_content_digest": (
                    TECHNICAL_CORRECTION_AMENDMENT_CONTENT_DIGEST
                ),
                "boundary": "exact public execute argv/cwd accepted before fallible startup validation",
            },
            "scientific_attempt": {
                "authorized": 1, "consumed": scientific,
                "remaining": 0 if scientific_unknown else 1 - scientific,
                "consumption_status": (
                    "UNKNOWN_CONSERVATIVELY_EXHAUSTED"
                    if scientific_unknown
                    else ("CONSUMED" if scientific else "NOT_CONSUMED")
                ),
                "boundary": "after PREEXECUTION passes, immediately before the first scientific input or model-state open",
                "complete_only_after_independent_payload_validation": True,
                "complete": science_complete,
            },
            "publication_attempt": {
                "authorized": publication_attempt_number,
                "consumed": publication,
                "remaining": publication_attempt_number - publication,
                "attempt_number": publication_attempt_number,
                "boundary": "after an independently validated immutable payload, before the first presentation output write",
                "presentation_retry_authority": retry,
            },
            "automatic_retry": False,
            "unknown_start_state_retry_authorized": False,
            "failed_or_unvalidated_output_reuse": False,
            "independently_validated_payload_reuse_for_presentation": (
                publication_attempt_number > 1
            ),
            "new_scientific_attempt_for_presentation_retry": False,
        }
    )


def validate_attempt_accounting(value: Mapping[str, Any]) -> dict[str, Any]:
    validate_self_digest(value)
    state = value.get("state")
    publication = value.get("publication_attempt")
    rebuilt = (
        build_attempt_accounting(
            state,
            publication_attempt_number=publication.get("attempt_number"),
            presentation_retry_authority=publication.get(
                "presentation_retry_authority"
            ),
        )
        if isinstance(state, str) and type(publication) is dict
        else None
    )
    if value != rebuilt:
        raise V2ContractError("attempt accounting drift")
    return copy.deepcopy(value)


