def validate_output_schema(value: Mapping[str, Any]) -> dict[str, Any]:
    validate_self_digest(value)
    rebuilt = build_output_schema()
    if value != rebuilt:
        raise V2ContractError("V2 output-schema drift")
    return copy.deepcopy(value)


def build_authority_payloads(
    repo_root: str | Path = REPO_ROOT,
) -> dict[str, bytes]:
    """Build, but never write, the exact six-file V2 authority set."""

    root = Path(repo_root)
    amendment_bytes, _amendment_observation = (
        _read_claim_critical_regular_file_anchored_no_follow(
            repo_root=root,
            relative_path=str(
                TRACKED_TECHNICAL_CORRECTION_AMENDMENT_PATH
            ),
            expected_sha256=TECHNICAL_CORRECTION_AMENDMENT_SHA256,
            expected_bytes=TECHNICAL_CORRECTION_AMENDMENT_BYTES,
        )
    )
    build_technical_correction_amendment_authority(root)
    invariance = build_scientific_invariance_receipt(repo_root)
    allow_list = build_allow_list()
    closure = build_source_closure(repo_root)
    validate_source_closure(closure)
    contract = build_contract(
        scientific_invariance_receipt=invariance,
        source_closure=closure,
        allow_list=allow_list,
    )
    output_schema = build_output_schema()
    return {
        str(TRACKED_SCIENTIFIC_INVARIANCE_PATH): (
            canonical_json_bytes(invariance) + b"\n"
        ),
        str(TRACKED_CONTRACT_PATH): canonical_json_bytes(contract) + b"\n",
        str(TRACKED_OUTPUT_SCHEMA_PATH): (
            canonical_json_bytes(output_schema) + b"\n"
        ),
        str(TRACKED_ALLOW_LIST_PATH): (
            canonical_json_bytes(allow_list) + b"\n"
        ),
        str(TRACKED_SOURCE_CLOSURE_PATH): (
            canonical_json_bytes(closure) + b"\n"
        ),
        str(TRACKED_TECHNICAL_CORRECTION_AMENDMENT_PATH): amendment_bytes,
    }


def validate_authority_payloads(
    values: Mapping[str, bytes], *, repo_root: str | Path = REPO_ROOT
) -> dict[str, bytes]:
    if not _has_exact_keys(values, AUTHORITY_PATHS):
        raise V2ContractError("V2 authority payload path set drift")
    rebuilt = build_authority_payloads(repo_root)
    if values != rebuilt or any(type(payload) is not bytes for payload in values.values()):
        raise V2ContractError("V2 authority payload bytes drift")
    return copy.deepcopy(values)


def _scientific_constant_rows() -> list[dict[str, Any]]:
    if tuple(FROZEN_V1_SCIENTIFIC_CONSTANT_SHA256) != (
        FROZEN_V1_SCIENTIFIC_CONSTANT_NAMES
    ):
        raise V2ContractError("scientific constant authority order drift")
    rows = []
    for name in FROZEN_V1_SCIENTIFIC_CONSTANT_NAMES:
        if not hasattr(V1, name):
            raise V2ContractError(f"missing frozen V1 constant: {name}")
        normalized = _normalize_json(getattr(V1, name))
        digest = canonical_json_sha256(normalized)
        if digest != FROZEN_V1_SCIENTIFIC_CONSTANT_SHA256[name]:
            raise V2ContractError(f"frozen V1 constant drift: {name}")
        rows.append({"name": name, "value": normalized, "sha256": digest})
    return rows


def build_scientific_invariance_receipt(
    repo_root: str | Path = REPO_ROOT,
) -> dict[str, Any]:
    V1.validate_contract(V1.CONTRACT)
    V1.validate_output_schema(V1.OUTPUT_SCHEMA)
    V1.validate_evaluator_fixture(V1.EVALUATOR_FIXTURE)
    if V1.CONTRACT_SHA256 != "1667f325be2c835a6222dc90bb684f373a06b365d59b70e9746fd7adb052c382":
        raise V2ContractError("frozen V1 contract digest drift")
    if V1.OUTPUT_SCHEMA_SHA256 != "e66798b015a2068f5be252dd3c0e4bc0b84aef4cf262d9b27b38089d65098338":
        raise V2ContractError("frozen V1 output-schema digest drift")
    rows = _scientific_constant_rows()
    source_custody = build_frozen_v1_source_custody(repo_root)
    return attach_self_digest(
        {
            "schema": SCIENTIFIC_INVARIANCE_SCHEMA,
            "source_experiment_id": SOURCE_EXPERIMENT_ID,
            "v1_scientific_freeze_commit": V1_SCIENTIFIC_FREEZE_COMMIT,
            "constant_rows": rows,
            "constant_count": len(rows),
            "frozen_contract": copy.deepcopy(V1.CONTRACT),
            "frozen_contract_sha256": V1.CONTRACT_SHA256,
            "frozen_output_schema": copy.deepcopy(V1.OUTPUT_SCHEMA),
            "frozen_output_schema_sha256": V1.OUTPUT_SCHEMA_SHA256,
            "frozen_evaluator_fixture": copy.deepcopy(V1.EVALUATOR_FIXTURE),
            "frozen_evaluator_fixture_sha256": V1.EVALUATOR_FIXTURE_SHA256,
            "frozen_tracked_authority_bindings": copy.deepcopy(
                FROZEN_V1_AUTHORITY_FILE_BINDINGS
            ),
            "frozen_source_bindings": copy.deepcopy(FROZEN_V1_SOURCE_BINDINGS),
            "frozen_source_custody": source_custody,
            "foreground_runtime_import_authority": (
                build_foreground_runtime_import_authority()
            ),
            "active_v2_scientific_scope": (
                "exact V1 scientific constants, targets, model, metrics, gates, and conditional decision tree"
            ),
            "historical_context_only": [
                "V1 execution retry policy",
                "V1 output-root and result/report layout",
                "V1 enclosing-result-commit publication policy",
                "V1 correction replay control flow",
            ],
            "v1_panel_already_outcome_observed": True,
            "development_only": True,
            "claim_bearing": False,
            "scientific_constants_equal": True,
            "scientific_contract_equal": True,
            "scientific_output_schema_equal": True,
            "scientific_source_equal": True,
            "pass": True,
        }
    )


def validate_scientific_invariance_receipt(
    value: Mapping[str, Any], *, repo_root: str | Path = REPO_ROOT
) -> dict[str, Any]:
    validate_self_digest(value)
    rebuilt = build_scientific_invariance_receipt(repo_root)
    if value != rebuilt:
        raise V2ContractError("scientific invariance receipt drift")
    return copy.deepcopy(value)


def scientific_invariance_receipt_bytes(value: Mapping[str, Any]) -> bytes:
    validate_scientific_invariance_receipt(value)
    return canonical_json_bytes(value) + b"\n"


