def build_scientific_decision(
    *,
    stage_a_decisions: Mapping[str, Any],
    stage_b_decisions: Mapping[str, Any] | None,
    stage_c_decisions: Mapping[str, Any] | None,
) -> dict[str, Any]:
    """Reproduce the exact frozen ``_primary_and_secondaries`` tree."""

    if type(stage_a_decisions) is not dict:
        raise V2ContractError("Stage-A decision object drift")
    try:
        true_pass = stage_a_decisions["true_future_gate"]["pass"]
        incremental_pass = stage_a_decisions["true_incremental_value"]["pass"]
        derangement_pass = stage_a_decisions["derangement"]["pass"]
    except (KeyError, TypeError) as exc:
        raise V2ContractError("Stage-A decision fields absent") from exc
    if any(
        type(item) is not bool
        for item in (true_pass, incremental_pass, derangement_pass)
    ):
        raise V2ContractError("Stage-A decision gate type drift")
    true_gate = stage_a_decisions["true_future_gate"]
    incremental_gate = stage_a_decisions["true_incremental_value"]
    if (
        true_gate.get("classification")
        != (
            "TRUE_FUTURE_PLAN_AWARE_COST_SIGNAL"
            if true_pass
            else "TRUE_FUTURE_PLAN_AWARE_COST_NO_SIGNAL"
        )
        or (true_pass and not derangement_pass)
        or true_gate.get("criteria", {}).get(
            "future_derangement_material"
        ) is not derangement_pass
        or (
            not true_pass
            and (
                incremental_pass
                or incremental_gate.get("evaluated") is not False
                or incremental_gate.get("status")
                != "NOT_EVALUATED_TRUE_GATE_FAILED"
            )
        )
    ):
        raise V2ContractError("Stage-A decision implication drift")
    if not true_pass:
        if stage_b_decisions is not None or stage_c_decisions is not None:
            raise V2ContractError("Stage-A failure must leave B/C absent")
        if incremental_pass is not False:
            raise V2ContractError("failed Stage-A incremental gate must be false")
        primary = "PLAN_AWARE_JEPA_COST_NO_SIGNAL"
        secondary = ["ENCODER_ROUTE_INFORMATION_INSUFFICIENT"]
        proprio_supported = None
    else:
        if type(stage_b_decisions) is not dict:
            raise V2ContractError("Stage-A pass requires Stage B")
        try:
            predicted_pass = stage_b_decisions["predicted_gate"]["pass"]
            predicted_fail = stage_b_decisions[
                "all_predicted_substitutions_fail_materially"
            ]
            incremental_over_kinematics = stage_b_decisions[
                "incremental_over_kinematics"
            ]["pass"]
            proprio_supported = stage_b_decisions["proprioception_gate"][
                "pass"
            ]
        except (KeyError, TypeError) as exc:
            raise V2ContractError("Stage-B decision fields absent") from exc
        if any(
            type(item) is not bool
            for item in (
                predicted_pass,
                predicted_fail,
                incremental_over_kinematics,
                proprio_supported,
            )
        ):
            raise V2ContractError("Stage-B decision gate type drift")
        if (
            stage_b_decisions["predicted_gate"].get("classification")
            != (
                "TWO_STEP_PLAN_AWARE_JEPA_COST_SIGNAL"
                if predicted_pass
                else "TWO_STEP_PLAN_AWARE_JEPA_COST_NO_SIGNAL"
            )
            or stage_b_decisions["proprioception_gate"].get(
                "classification"
            )
            != (
                "PROPRIOCEPTIVE_ROUTE_CONTRIBUTION"
                if proprio_supported
                else "PROPRIOCEPTIVE_ROUTE_CONTRIBUTION_NOT_SUPPORTED"
            )
            or stage_b_decisions[
                "predicted_source_absolute_preservation"
            ].get("all_predicted_substitutions_fail_materially")
            is not predicted_fail
        ):
            raise V2ContractError("Stage-B decision implication drift")
        if not incremental_pass:
            primary = "KINEMATIC_BASELINE_DOMINANT"
            secondary = ["TRUE_FUTURE_PLAN_AWARE_COST_SIGNAL"]
            if derangement_pass:
                secondary.append(
                    "CANDIDATE_SPECIFIC_LATENT_ROUTE_INFORMATION_USED"
                )
        else:
            primary = V1.derive_primary_classification(
                true_gate_pass=True,
                true_incremental_gate_pass=True,
                rr_gate_pass=predicted_pass,
                all_predicted_substitutions_fail_materially=predicted_fail,
            )
            if primary == "TWO_STEP_PLAN_AWARE_JEPA_COST_SIGNAL":
                secondary = [
                    "TRUE_FUTURE_PLAN_AWARE_COST_SIGNAL",
                    "TRUE_FUTURE_JEPA_INCREMENTAL_ROUTE_VALUE",
                    "CANDIDATE_SPECIFIC_LATENT_ROUTE_INFORMATION_USED",
                    "TWO_STEP_PLAN_AWARE_JEPA_COST_SIGNAL",
                    "ROLLOUT_ROUTE_INFORMATION_SIGNAL",
                ]
                if incremental_over_kinematics:
                    secondary.append(
                        "JEPA_INCREMENTAL_ROUTE_VALUE_OVER_KINEMATICS"
                    )
            elif primary == "TRUE_FUTURE_COST_SIGNAL_PREDICTOR_ROUTE_NO_GO":
                secondary = [
                    "TRUE_FUTURE_PLAN_AWARE_COST_SIGNAL",
                    "TRUE_FUTURE_JEPA_INCREMENTAL_ROUTE_VALUE",
                    "CANDIDATE_SPECIFIC_LATENT_ROUTE_INFORMATION_USED",
                    "PREDICTOR_ROUTE_GEOMETRY_LOSS",
                ]
            else:
                raise V2ContractError("unexpected Stage-B primary")
        secondary.append("WRONG_PLANNING_READOUT")
        secondary.append(
            "PROPRIOCEPTIVE_ROUTE_CONTRIBUTION"
            if proprio_supported
            else "PROPRIOCEPTIVE_ROUTE_CONTRIBUTION_NOT_SUPPORTED"
        )
        if proprio_supported:
            if type(stage_c_decisions) is not dict:
                raise V2ContractError("proprio gate pass requires Stage C")
            try:
                classification = str(stage_c_decisions["classification"])
                dependence = str(stage_c_decisions["dependence_attribution"])
                substitution_gate = stage_c_decisions["substitution_gate"]
            except (KeyError, TypeError) as exc:
                raise V2ContractError("Stage-C decision fields absent") from exc
            if (
                type(substitution_gate) is not dict
                or substitution_gate.get("classification") != classification
                or substitution_gate.get("dependence_attribution")
                != dependence
                or stage_c_decisions.get(
                    "control_only_explanation_excluded"
                )
                is not substitution_gate.get("criteria", {}).get(
                    "not_explained_by_control_derangement_alone"
                )
            ):
                raise V2ContractError("Stage-C decision implication drift")
            secondary.append(classification)
            if dependence != classification:
                secondary.append(dependence)
        elif stage_c_decisions is not None:
            raise V2ContractError("failed proprio gate forbids Stage C")
    secondary = list(dict.fromkeys(secondary))
    if any(item not in V1.SECONDARY_CLASSIFICATIONS for item in secondary):
        raise V2ContractError("exact secondary classification tree drift")
    try:
        frozen_primary, frozen_secondary, next_experiment = (
            _v1_scientific_evaluator_module()._primary_and_secondaries(
                stage_a_decisions, stage_b_decisions, stage_c_decisions
            )
        )
    except Exception as exc:
        raise V2ContractError(
            "frozen primary/secondary decision rebuild failed"
        ) from exc
    if primary != frozen_primary or secondary != frozen_secondary:
        raise V2ContractError("frozen primary/secondary decision drift")
    return {
        "stage_a_decisions": copy.deepcopy(stage_a_decisions),
        "stage_b_decisions": copy.deepcopy(stage_b_decisions),
        "stage_c_decisions": copy.deepcopy(stage_c_decisions),
        "stage_a_gate_pass": true_pass,
        "true_incremental_gate_pass": incremental_pass,
        "proprio_contribution_supported": proprio_supported,
        "primary_classification": primary,
        "secondary_classifications": secondary,
        "next_experiment": next_experiment,
        "next_experiment_specification": copy.deepcopy(
            V1.NEXT_EXPERIMENT_SPECIFICATIONS[next_experiment]
        ),
        "development_only": True,
        "claim_bearing": False,
    }


def validate_scientific_decision(value: Mapping[str, Any]) -> dict[str, Any]:
    if not _has_exact_keys(value, (
        "stage_a_decisions", "stage_b_decisions", "stage_c_decisions",
        "stage_a_gate_pass", "true_incremental_gate_pass",
        "proprio_contribution_supported", "primary_classification",
        "secondary_classifications", "next_experiment",
        "next_experiment_specification", "development_only", "claim_bearing",
    )):
        raise V2ContractError("scientific decision schema drift")
    rebuilt = build_scientific_decision(
        stage_a_decisions=value["stage_a_decisions"],
        stage_b_decisions=value["stage_b_decisions"],
        stage_c_decisions=value["stage_c_decisions"],
    )
    if value != rebuilt:
        raise V2ContractError("scientific decision drift")
    return copy.deepcopy(value)


def _validate_scientific_counters(
    counters: Mapping[str, Any], *, payloads: int
) -> dict[str, int]:
    if not _has_exact_keys(counters, SCIENTIFIC_COUNTER_FIELDS):
        raise V2ContractError("scientific counter schema drift")
    normalized: dict[str, int] = {}
    for key in SCIENTIFIC_COUNTER_FIELDS:
        item = counters[key]
        if type(item) is not int or item < 0:
            raise V2ContractError("scientific counter value drift")
        normalized[key] = item
    if normalized["scientific_payloads"] != payloads:
        raise V2ContractError("scientific payload counter drift")
    return normalized


def _validate_artifact_map(
    artifacts: Mapping[str, Any], *, stage_execution: Mapping[str, Any]
) -> dict[str, Any]:
    if not _has_exact_keys(artifacts, SCIENTIFIC_ARTIFACT_AUTHORITY):
        raise V2ContractError("scientific artifact map drift")
    result: dict[str, Any] = {}
    stage_b = stage_execution["stage_b"]["executed"]
    stage_c = stage_execution["stage_c"]["executed"]
    for key, authority in SCIENTIFIC_ARTIFACT_AUTHORITY.items():
        required = authority["required"] is True
        if authority["required"] == "STAGE_B_EXECUTED":
            required = stage_b
        elif authority["required"] == "STAGE_C_EXECUTED":
            required = stage_c
        item = artifacts[key]
        if not required:
            if item is not None:
                raise V2ContractError(f"unexecuted artifact present: {key}")
            result[key] = None
            continue
        if item is None:
            raise V2ContractError(f"required scientific artifact absent: {key}")
        result[key] = validate_artifact_binding(
            item,
            expected_path=authority["path"],
            expected_rows=authority["rows"],
        )
    return result


SCIENTIFIC_COMPONENT_KEYS = (
    "preexecution_receipt",
    "foreground_runtime_import_custody",
    "attempt_root_fd_custody",
    "scientific_attempt_boundary_entry",
    "first_scientific_open_initiation",
    "first_scientific_open_receipt",
    "training_smoke_receipt",
    "training_receipt",
    "evaluation_contract",
    "evaluation_receipt",
    "metrics",
    "candidate_selections",
    "gate_decisions",
    "runtime_storage_custody",
    "static_input_stage_a_custody",
    "stage_b_gate_receipt",
    "proprio_helper_manifest",
    "proprio_helper_receipt",
    "proprio_helper_exit_custody",
    "proprio_worker_lifecycle_manifest",
    "static_input_stage_b_helper_custody",
    "stage_c_gate_receipt",
    "stage_c_helper_manifest",
    "stage_c_helper_receipt",
    "stage_c_helper_exit_custody",
    "stage_c_worker_lifecycle_manifest",
    "static_input_stage_c_helper_custody",
)


def build_runtime_storage_custody(
    *,
    attempt_root: str | Path,
    producer_process_identity: Mapping[str, Any],
    started_monotonic_ns: int,
    payload_frozen_monotonic_ns: int,
    peak_rss_kib: int,
    technical_file_count_before_payload: int,
    technical_bytes_before_payload: int,
    environment_names: Sequence[str],
    environment_sha256: str,
) -> dict[str, Any]:
    root = Path(attempt_root).absolute()
    expected_internal_argv(PHASE2_VALIDATOR_MODE, root)
    producer = _validate_process_identity(producer_process_identity)
    if producer["argv"] != list(PUBLIC_EXECUTE_ARGV):
        raise V2ContractError("runtime custody producer argv drift")
    if (
        type(started_monotonic_ns) is not int
        or type(payload_frozen_monotonic_ns) is not int
        or started_monotonic_ns < 0
        or payload_frozen_monotonic_ns < started_monotonic_ns
        or type(peak_rss_kib) is not int
        or peak_rss_kib < 0
        or type(technical_file_count_before_payload) is not int
        or technical_file_count_before_payload < 1
        or type(technical_bytes_before_payload) is not int
        or technical_bytes_before_payload < 0
    ):
        raise V2ContractError("runtime/storage numeric custody drift")
    names = list(environment_names)
    if (
        names != sorted(set(names))
        or any(type(item) is not str or not item for item in names)
        or not isinstance(environment_sha256, str)
        or not _SHA256_RE.fullmatch(environment_sha256)
    ):
        raise V2ContractError("runtime environment custody drift")
    return attach_self_digest(
        {
            "schema": RUNTIME_STORAGE_CUSTODY_SCHEMA,
            "experiment_id": EXPERIMENT_ID,
            "attempt_root": str(root),
            "producer_process_identity": producer,
            "started_monotonic_ns": started_monotonic_ns,
            "payload_frozen_monotonic_ns": payload_frozen_monotonic_ns,
            "elapsed_monotonic_ns": (
                payload_frozen_monotonic_ns - started_monotonic_ns
            ),
            "peak_rss_kib": peak_rss_kib,
            "technical_file_count_before_payload": (
                technical_file_count_before_payload
            ),
            "technical_bytes_before_payload": technical_bytes_before_payload,
            "environment_names": names,
            "environment_sha256": environment_sha256,
            "workers": V1.CPU_WORKERS,
            "numerical_thread_environment": copy.deepcopy(
                V1.NUMERICAL_THREAD_ENV
            ),
            "failed_output_files_reused": 0,
            "correction_replay_receipts_or_gates_used": False,
            "pass": True,
        }
    )


def validate_runtime_storage_custody(
    value: Mapping[str, Any],
) -> dict[str, Any]:
    validate_self_digest(value)
    rebuilt = build_runtime_storage_custody(
        attempt_root=value.get("attempt_root"),
        producer_process_identity=value.get("producer_process_identity"),
        started_monotonic_ns=value.get("started_monotonic_ns"),
        payload_frozen_monotonic_ns=value.get(
            "payload_frozen_monotonic_ns"
        ),
        peak_rss_kib=value.get("peak_rss_kib"),
        technical_file_count_before_payload=value.get(
            "technical_file_count_before_payload"
        ),
        technical_bytes_before_payload=value.get(
            "technical_bytes_before_payload"
        ),
        environment_names=value.get("environment_names"),
        environment_sha256=value.get("environment_sha256"),
    )
    if value != rebuilt:
        raise V2ContractError("runtime/storage custody drift")
    return copy.deepcopy(value)


def _validate_json_component_binding(
    value: Mapping[str, Any], binding: Mapping[str, Any]
) -> dict[str, Any]:
    validated = validate_self_digest(value)
    payload = canonical_json_bytes(validated) + b"\n"
    if (
        binding["sha256"] != hashlib.sha256(payload).hexdigest()
        or binding["bytes"] != len(payload)
        or binding["content_digest"] != validated["content_digest"]
    ):
        raise V2ContractError("scientific component byte binding drift")
    return validated


def build_scientific_component_payloads(
    *,
    attempt_id: str,
    stage_execution: Mapping[str, Any],
    scientific_decision: Mapping[str, Any],
    artifact_bindings: Mapping[str, Any],
    component_values: Mapping[str, Any],
) -> dict[str, Any]:
    if not isinstance(attempt_id, str) or not _ATTEMPT_ID_RE.fullmatch(
        attempt_id
    ):
        raise V2ContractError("scientific component attempt id drift")
    stages = validate_stage_execution(stage_execution)
    decision = validate_scientific_decision(scientific_decision)
    artifacts = _validate_artifact_map(
        artifact_bindings, stage_execution=stages
    )
    if not _has_exact_keys(component_values, SCIENTIFIC_COMPONENT_KEYS):
        raise V2ContractError("scientific component key drift")
    component_to_artifact = {
        key: key for key in SCIENTIFIC_COMPONENT_KEYS
    }
    values: dict[str, Any] = {}
    stage_b = stages["stage_b"]["executed"]
    stage_c = stages["stage_c"]["executed"]
    stage_b_keys = {
        "stage_b_gate_receipt", "proprio_helper_manifest",
        "proprio_helper_receipt", "proprio_helper_exit_custody",
        "proprio_worker_lifecycle_manifest",
        "static_input_stage_b_helper_custody",
    }
    stage_c_keys = {
        "stage_c_gate_receipt", "stage_c_helper_manifest",
        "stage_c_helper_receipt", "stage_c_helper_exit_custody",
        "stage_c_worker_lifecycle_manifest",
        "static_input_stage_c_helper_custody",
    }
    for key in SCIENTIFIC_COMPONENT_KEYS:
        required = key not in stage_b_keys | stage_c_keys
        if key in stage_b_keys:
            required = bool(stage_b)
        elif key in stage_c_keys:
            required = bool(stage_c)
        item = component_values[key]
        binding = artifacts[component_to_artifact[key]]
        if not required:
            if item is not None or binding is not None:
                raise V2ContractError(
                    f"unexecuted scientific component present: {key}"
                )
            values[key] = None
            continue
        if type(item) is not dict or binding is None:
            raise V2ContractError(f"scientific component absent: {key}")
        values[key] = _validate_json_component_binding(item, binding)

    runtime = validate_runtime_storage_custody(
        values["runtime_storage_custody"]
    )
    if runtime["attempt_root"] != str(
        OUTPUT_ROOT.parent / f".{OUTPUT_ROOT.name}.attempt-{attempt_id}"
    ):
        raise V2ContractError("runtime/component attempt-root drift")
    preexecution = validate_preexecution_receipt(
        values["preexecution_receipt"]
    )
    foreground_runtime = (
        validate_phase1_foreground_runtime_import_custody(
            values["foreground_runtime_import_custody"]
        )
    )
    root_fd_custody = validate_attempt_root_fd_custody(
        values["attempt_root_fd_custody"]
    )
    boundary_entry = validate_scientific_attempt_boundary_entry_receipt(
        values["scientific_attempt_boundary_entry"],
        preexecution_receipt=preexecution,
    )
    first_open_initiation = (
        validate_first_scientific_open_initiation_receipt(
            values["first_scientific_open_initiation"],
            boundary_entry_receipt=boundary_entry,
            preexecution_receipt=preexecution,
        )
    )
    first_open = validate_first_scientific_open_receipt(
        values["first_scientific_open_receipt"],
        boundary_entry_receipt=boundary_entry,
        preexecution_receipt=preexecution,
    )
    if (
        preexecution["attempt_id"] != attempt_id
        or boundary_entry["attempt_id"] != attempt_id
        or first_open_initiation["attempt_id"] != attempt_id
        or first_open["attempt_id"] != attempt_id
        or first_open["first_open_initiation_receipt"]
        != first_open_initiation
        or preexecution["foreground_runtime_import_custody"]
        != foreground_runtime
        or foreground_runtime["producer_process_identity"]
        != runtime["producer_process_identity"]
        or preexecution["producer_process_identity"]
        != runtime["producer_process_identity"]
        or preexecution["attempt_root_fd_custody"] != root_fd_custody
    ):
        raise V2ContractError("PREEXEC/component boundary drift")
    stage_a_static = validate_static_input_stage_custody(
        values["static_input_stage_a_custody"]
    )
    if (
        stage_a_static["stage_id"] != "PHASE1_STAGE_A"
        or stage_a_static["stage_process_identity"]
        != runtime["producer_process_identity"]
        or stage_a_static["attempt_root_fd_custody_content_digest"]
        != root_fd_custody["content_digest"]
    ):
        raise V2ContractError("Stage-A static-input custody drift")
    smoke = values["training_smoke_receipt"]
    expected_smoke_checks = (
        "fit_only_split_exclusion",
        "no_calibration_or_heldout_rows_opened",
        "candidate_waypoint_invariant",
        "spatial_24x32_row_major_order_preserved",
        "action_change_alters_latent_condition_score",
        "latent_change_alters_latent_condition_score",
        "latent_change_cannot_enter_no_latent_condition",
        "latent_branch_zero_exact_kinematic_plus_base",
        "finite_loss_and_gradients",
        "checkpoint_save_reload_exact",
        "deterministic_repeated_inference",
        "model_forward_inputs_exclude_outcome_fields",
    )
    if (
        smoke.get("schema") != "plan_aware_monotone_jepa_training_smoke_v1"
        or not _has_exact_keys(smoke.get("checks"), expected_smoke_checks)
        or not all(item is True for item in smoke["checks"].values())
        or smoke.get("calibration_rows_opened") != 0
        or smoke.get("heldout_rows_opened") != 0
        or smoke.get("scientific_hyperparameters_changed") is not False
        or smoke.get("pass") is not True
    ):
        raise V2ContractError("training-smoke component drift")
    metrics = values["metrics"]
    if (
        metrics.get("schema")
        != "plan_aware_monotone_jepa_cost_v2.scientific_metrics.v1"
        or metrics.get("attempt_id") != attempt_id
        or metrics.get("stage_a_decisions")
        != decision["stage_a_decisions"]
        or (metrics.get("stage_b") is None) != (not stage_b)
        or (metrics.get("stage_c") is None) != (not stage_c)
        or metrics.get("scientific_decision") != decision
        or metrics.get("historical_failed_output_metrics_opened") != 0
        or metrics.get("historical_failed_output_metrics_reused") != 0
        or metrics.get("raw_goal_cosine_inference_executions") != 0
    ):
        raise V2ContractError("scientific metrics component drift")
    stage_a_metrics = metrics.get("stage_a")
    if type(stage_a_metrics) is not dict or type(
        stage_a_metrics.get("heldout")
    ) is not dict:
        raise V2ContractError("Stage-A heldout metrics absent")
    exact_stage_a = _exact_stage_a_decisions(stage_a_metrics["heldout"])
    if exact_stage_a != decision["stage_a_decisions"]:
        raise V2ContractError("payload Stage-A decisions do not regenerate")
    exact_stage_b = None
    if stage_b:
        stage_b_metrics = metrics.get("stage_b")
        if type(stage_b_metrics) is not dict or type(
            stage_b_metrics.get("summaries")
        ) is not dict or type(
            stage_b_metrics["summaries"].get("heldout")
        ) is not dict:
            raise V2ContractError("Stage-B heldout metrics absent")
        exact_stage_b = _exact_stage_b_decisions(
            stage_a_decisions=exact_stage_a,
            stage_a_heldout_summaries=stage_a_metrics["heldout"],
            stage_b_heldout_summaries=stage_b_metrics["summaries"][
                "heldout"
            ],
        )
        if exact_stage_b != decision["stage_b_decisions"]:
            raise V2ContractError("payload Stage-B decisions do not regenerate")
    if stage_c:
        stage_c_metrics = metrics.get("stage_c")
        if (
            type(stage_c_metrics) is not dict
            or type(stage_c_metrics.get("summaries")) is not dict
            or type(stage_c_metrics["summaries"].get("heldout")) is not dict
            or type(stage_c_metrics.get("candidate_action_sensitivity"))
            is not dict
            or type(metrics.get("stage_b")) is not dict
        ):
            raise V2ContractError("Stage-C decision evidence absent")
        exact_stage_c = _exact_stage_c_decisions(
            stage_b=metrics["stage_b"],
            stage_c_heldout_summaries=stage_c_metrics["summaries"][
                "heldout"
            ],
            action_sensitivity=stage_c_metrics[
                "candidate_action_sensitivity"
            ],
        )
        if exact_stage_c != decision["stage_c_decisions"]:
            raise V2ContractError("payload Stage-C decisions do not regenerate")
    selections = values["candidate_selections"]
    if (
        selections.get("schema")
        != "plan_aware_monotone_jepa_cost_v2.candidate_selections.v1"
        or selections.get("attempt_id") != attempt_id
        or type(selections.get("rows")) is not list
        or len(selections["rows"]) != 48
        or selections.get("row_count") != 48
    ):
        raise V2ContractError("candidate-selection component drift")
    gates = values["gate_decisions"]
    if not _has_exact_keys(gates, (
        "schema", "stage_a", "stage_b", "stage_c",
        "scientific_decision", "forced_stage_a_pass",
        "correction_replay_control_flow_used", "content_digest",
    )) or (
        gates["schema"]
        != "plan_aware_monotone_jepa_cost_v2.gate_decisions.v1"
        or gates["stage_a"] != decision["stage_a_decisions"]
        or gates["stage_b"] != decision["stage_b_decisions"]
        or gates["stage_c"] != decision["stage_c_decisions"]
        or gates["scientific_decision"] != decision
        or gates["forced_stage_a_pass"] is not False
        or gates["correction_replay_control_flow_used"] is not False
    ):
        raise V2ContractError("gate-decision component drift")
    validate_self_digest(values["training_receipt"])
    validate_self_digest(values["evaluation_contract"])
    validate_self_digest(values["evaluation_receipt"])
    if values["evaluation_receipt"].get("schema") != (
        "plan_aware_monotone_jepa_cost_v2.evaluation_lifecycle.v1"
    ):
        raise V2ContractError("evaluation lifecycle component drift")
    if stage_b:
        stage_b_gate = validate_stage_b_gate_receipt(
            values["stage_b_gate_receipt"],
            preexecution_receipt=preexecution,
        )
        helper_manifest = validate_phase1_helper_manifest(
            values["proprio_helper_manifest"]
        )
        helper_receipt = validate_phase1_helper_receipt(
            values["proprio_helper_receipt"]
        )
        helper_exit = validate_phase1_helper_exit_custody(
            values["proprio_helper_exit_custody"]
        )
        worker_manifest = validate_phase1_worker_lifecycle_manifest(
            values["proprio_worker_lifecycle_manifest"]
        )
        static_stage = validate_static_input_multi_process_stage_custody(
            values["static_input_stage_b_helper_custody"],
            helper_process_custody=helper_receipt[
                "static_input_process_custody"
            ],
            worker_lifecycle_manifest=worker_manifest,
        )
        worker_binding = artifacts["proprio_worker_lifecycle_manifest"]
        if (
            helper_manifest["worker_lifecycle_manifest_binding"]
            != worker_binding
            or stage_b_gate["stage_a_gate_evidence_binding"]
            != artifacts["stage_a_gate_evidence"]
            or stage_b_gate["stage_a_gate_evidence"][
                "stage_a_heldout_summaries"
            ] != stage_a_metrics["heldout"]
            or helper_receipt["worker_lifecycle_manifest_binding"]
            != worker_binding
            or helper_exit["helper_receipt"] != helper_receipt
            or helper_receipt["child_attempt_root_fd_binding"][
                "attempt_root_fd_custody"
            ] != root_fd_custody
            or worker_manifest["parent_helper_process_identity"]
            != helper_receipt["process_identity"]
            or any(
                row["child_attempt_root_fd_binding"][
                    "attempt_root_fd_custody"
                ] != root_fd_custody
                or
                row["started_monotonic_ns"]
                < helper_exit["started_monotonic_ns"]
                or row["ended_monotonic_ns"]
                > helper_exit["ended_monotonic_ns"]
                for row in worker_manifest["worker_exit_custodies"]
            )
            or static_stage["stage_id"] != "PHASE1_STAGE_B_HELPER"
            or static_stage["helper_process_identity"]
            != helper_receipt["process_identity"]
            or static_stage["attempt_root_fd_custody_content_digest"]
            != root_fd_custody["content_digest"]
            or static_stage["helper_process_custody_content_digest"]
            != helper_receipt["static_input_process_custody"][
                "content_digest"
            ]
            or helper_receipt["static_input_process_custody"][
                "process_started_monotonic_ns"
            ] < helper_exit["started_monotonic_ns"]
            or helper_receipt["static_input_process_custody"][
                "process_ended_monotonic_ns"
            ] > helper_exit["ended_monotonic_ns"]
        ):
            raise V2ContractError("proprio worker/helper cross-binding drift")
    if stage_c:
        stage_c_gate = validate_stage_c_gate_receipt(
            values["stage_c_gate_receipt"],
            preexecution_receipt=preexecution,
        )
        helper_manifest = validate_phase1_helper_manifest(
            values["stage_c_helper_manifest"]
        )
        helper_receipt = validate_phase1_helper_receipt(
            values["stage_c_helper_receipt"]
        )
        helper_exit = validate_phase1_helper_exit_custody(
            values["stage_c_helper_exit_custody"]
        )
        worker_manifest = validate_phase1_worker_lifecycle_manifest(
            values["stage_c_worker_lifecycle_manifest"]
        )
        static_stage = validate_static_input_multi_process_stage_custody(
            values["static_input_stage_c_helper_custody"],
            helper_process_custody=helper_receipt[
                "static_input_process_custody"
            ],
            worker_lifecycle_manifest=worker_manifest,
        )
        worker_binding = artifacts["stage_c_worker_lifecycle_manifest"]
        if (
            helper_manifest["worker_lifecycle_manifest_binding"]
            != worker_binding
            or stage_c_gate["stage_b_gate_evidence_binding"]
            != artifacts["stage_b_gate_evidence"]
            or stage_c_gate["stage_b_gate_evidence"][
                "stage_b_heldout_summaries"
            ] != metrics["stage_b"]["summaries"]["heldout"]
            or helper_receipt["worker_lifecycle_manifest_binding"]
            != worker_binding
            or helper_exit["helper_receipt"] != helper_receipt
            or helper_receipt["child_attempt_root_fd_binding"][
                "attempt_root_fd_custody"
            ] != root_fd_custody
            or worker_manifest["parent_helper_process_identity"]
            != helper_receipt["process_identity"]
            or any(
                row["child_attempt_root_fd_binding"][
                    "attempt_root_fd_custody"
                ] != root_fd_custody
                or
                row["started_monotonic_ns"]
                < helper_exit["started_monotonic_ns"]
                or row["ended_monotonic_ns"]
                > helper_exit["ended_monotonic_ns"]
                for row in worker_manifest["worker_exit_custodies"]
            )
            or static_stage["stage_id"] != "PHASE1_STAGE_C_HELPER"
            or static_stage["helper_process_identity"]
            != helper_receipt["process_identity"]
            or static_stage["attempt_root_fd_custody_content_digest"]
            != root_fd_custody["content_digest"]
            or static_stage["helper_process_custody_content_digest"]
            != helper_receipt["static_input_process_custody"][
                "content_digest"
            ]
            or helper_receipt["static_input_process_custody"][
                "process_started_monotonic_ns"
            ] < helper_exit["started_monotonic_ns"]
            or helper_receipt["static_input_process_custody"][
                "process_ended_monotonic_ns"
            ] > helper_exit["ended_monotonic_ns"]
        ):
            raise V2ContractError("Stage-C worker/helper cross-binding drift")
    return attach_self_digest(
        {
            "schema": SCIENTIFIC_COMPONENT_PAYLOAD_SCHEMA,
            "experiment_id": EXPERIMENT_ID,
            "attempt_id": attempt_id,
            "values": values,
            "artifact_bindings": {
                key: copy.deepcopy(artifacts[key])
                for key in SCIENTIFIC_COMPONENT_KEYS
            },
            "complete_presentation_source": True,
            "scientific_values_frozen_before_phase_2": True,
            "failed_output_files_reused": 0,
            "pass": True,
        }
    )


def validate_scientific_component_payloads(
    value: Mapping[str, Any],
    *,
    stage_execution: Mapping[str, Any],
    scientific_decision: Mapping[str, Any],
    artifact_bindings: Mapping[str, Any],
) -> dict[str, Any]:
    validate_self_digest(value)
    rebuilt = build_scientific_component_payloads(
        attempt_id=value.get("attempt_id"),
        stage_execution=stage_execution,
        scientific_decision=scientific_decision,
        artifact_bindings=artifact_bindings,
        component_values=value.get("values"),
    )
    if value != rebuilt:
        raise V2ContractError("scientific component payload drift")
    return copy.deepcopy(value)


def _validate_scientific_counter_semantics(
    counters: Mapping[str, int],
    *,
    stage_execution: Mapping[str, Any],
    scientific_component_payloads: Mapping[str, Any],
) -> None:
    stage_b = int(stage_execution["stage_b"]["executed"])
    stage_c = int(stage_execution["stage_c"]["executed"])
    training = scientific_component_payloads["values"]["training_receipt"]
    histories = training.get("training_history")
    if type(histories) is not dict or len(histories) != 2:
        raise V2ContractError("training history counter custody drift")
    optimizer_updates = 0
    for history in histories.values():
        if isinstance(history, (str, bytes)) or not isinstance(
            history, Sequence
        ) or len(history) != 60:
            raise V2ContractError("training epoch history drift")
        for row in history:
            if type(row) is not dict or type(row.get("optimizer_steps")) is not int:
                raise V2ContractError("optimizer-step custody drift")
            optimizer_updates += row["optimizer_steps"]
    expected = {
        "fit_states_opened": V1.ROLE_STATE_COUNTS["fit"],
        "fit_rows_opened": V1.ROLE_ROW_COUNTS["fit"],
        "calibration_states_opened": V1.ROLE_STATE_COUNTS["calibration"],
        "calibration_rows_opened": V1.ROLE_ROW_COUNTS["calibration"],
        "heldout_states_opened": V1.ROLE_STATE_COUNTS["heldout"],
        "heldout_rows_opened": V1.ROLE_ROW_COUNTS["heldout"],
        "route_labels_opened": 576,
        "true_future_latents_opened": 576,
        "predicted_latents_opened": 3456 * stage_b + 5184 * stage_c,
        "predictor_checkpoints_opened": 2 * stage_b + 3 * stage_c,
        "route_cost_checkpoints_opened": 2,
        "model_initializations": 2,
        "optimizer_updates": optimizer_updates,
        "training_epochs": 120,
        "scientific_score_rows": (
            2304 + 2304 * stage_b + 9216 * stage_c
        ),
        "candidate_selections": 48,
        "scientific_metrics": 1,
        "scientific_payloads": 1,
        "failed_output_files_opened_for_reuse": 0,
        "correction_replay_receipts_read": 0,
        "future_proprioception_reads": 0,
        "route_outcome_reads": 0,
        "raw_goal_cosine_executions": 0,
    }
    if counters != expected:
        raise V2ContractError("scientific counter semantics drift")


def build_immutable_scientific_payload(
    *,
    attempt_id: str,
    source_freeze_commit: str,
    scientific_invariance_receipt: Mapping[str, Any],
    namespace_and_nonreuse_receipt: Mapping[str, Any],
    artifact_bindings: Mapping[str, Any],
    checkpoint_state_digests: Mapping[str, Any],
    scientific_decision: Mapping[str, Any],
    scientific_counters: Mapping[str, Any],
    scientific_component_payloads: Mapping[str, Any],
) -> dict[str, Any]:
    if not isinstance(attempt_id, str) or not _ATTEMPT_ID_RE.fullmatch(attempt_id):
        raise V2ContractError("attempt id drift")
    if attempt_id != CORRECTED_TECHNICAL_STARTUP_ATTEMPT_ID:
        raise V2ContractError("corrected immutable payload identity drift")
    if not isinstance(source_freeze_commit, str) or not re.fullmatch(
        r"[0-9a-f]{40}", source_freeze_commit
    ):
        raise V2ContractError("V2 source-freeze commit drift")
    invariance = validate_scientific_invariance_receipt(
        scientific_invariance_receipt
    )
    nonreuse = validate_namespace_and_nonreuse_receipt(
        namespace_and_nonreuse_receipt, expected_attempt_id=attempt_id
    )
    decision = validate_scientific_decision(scientific_decision)
    stages = build_stage_execution(
        stage_a_gate_pass=decision["stage_a_gate_pass"],
        proprio_contribution_supported=decision[
            "proprio_contribution_supported"
        ],
    )
    artifacts = _validate_artifact_map(
        artifact_bindings, stage_execution=stages
    )
    if type(checkpoint_state_digests) is not dict or tuple(
        checkpoint_state_digests
    ) != ("no_latent", "latent_true_future"):
        raise V2ContractError("checkpoint-state digest schema drift")
    for digest in checkpoint_state_digests.values():
        if not isinstance(digest, str) or not _SHA256_RE.fullmatch(digest):
            raise V2ContractError("checkpoint-state digest malformed")
    counters = _validate_scientific_counters(scientific_counters, payloads=1)
    components = validate_scientific_component_payloads(
        scientific_component_payloads,
        stage_execution=stages,
        scientific_decision=decision,
        artifact_bindings=artifacts,
    )
    preexecution = components["values"]["preexecution_receipt"]
    failed_nonreuse = validate_failed_technical_startup_nonreuse_custody(
        nonreuse["failed_technical_startup_nonreuse_custody"],
        reverify_live=False,
    )
    if (
        preexecution["source_freeze_commit"] != source_freeze_commit
        or preexecution["attempt_id"] != attempt_id
        or preexecution["technical_correction_amendment_authority"]
        != failed_nonreuse["amendment_authority"]
        or preexecution["failed_technical_startup_nonreuse_custody"]
        != failed_nonreuse
        or nonreuse["technical_correction_amendment_authority"]
        != failed_nonreuse["amendment_authority"]
    ):
        raise V2ContractError("payload/PREEXEC source-freeze drift")
    _validate_scientific_counter_semantics(
        counters,
        stage_execution=stages,
        scientific_component_payloads=components,
    )
    accounting = build_attempt_accounting("IMMUTABLE_PAYLOAD_FROZEN")
    return attach_self_digest(
        {
            "schema": IMMUTABLE_SCIENTIFIC_PAYLOAD_SCHEMA,
            "experiment_id": EXPERIMENT_ID,
            "source_experiment_id": SOURCE_EXPERIMENT_ID,
            "attempt_id": attempt_id,
            "source_freeze_commit": source_freeze_commit,
            "scientific_invariance_receipt": invariance,
            "namespace_and_nonreuse_receipt": nonreuse,
            "technical_correction_amendment_authority": failed_nonreuse[
                "amendment_authority"
            ],
            "failed_technical_startup_nonreuse_custody": failed_nonreuse,
            "failed_technical_startup_nonreuse_content_digest": (
                failed_nonreuse["content_digest"]
            ),
            "prior_failed_technical_startup_attempt_id": (
                FAILED_TECHNICAL_STARTUP_ATTEMPT_ID
            ),
            "corrected_technical_startup_attempt_id": (
                CORRECTED_TECHNICAL_STARTUP_ATTEMPT_ID
            ),
            "attempt_accounting": accounting,
            "checkpoint_state_digests": copy.deepcopy(
                checkpoint_state_digests
            ),
            "artifact_bindings": artifacts,
            "stage_execution": stages,
            "scientific_decision": decision,
            "scientific_component_payloads": components,
            "scientific_counters": counters,
            "frozen_before_independent_validation": True,
            "immutable_after_freeze": True,
            "presentation_fields_present": False,
            "failed_output_files_reused": 0,
        }
    )


def validate_immutable_scientific_payload(
    value: Mapping[str, Any],
) -> dict[str, Any]:
    validate_self_digest(value)
    if not _has_exact_keys(value, (
        "schema", "experiment_id", "source_experiment_id", "attempt_id",
        "source_freeze_commit",
        "scientific_invariance_receipt", "namespace_and_nonreuse_receipt",
        "technical_correction_amendment_authority",
        "failed_technical_startup_nonreuse_custody",
        "failed_technical_startup_nonreuse_content_digest",
        "prior_failed_technical_startup_attempt_id",
        "corrected_technical_startup_attempt_id",
        "attempt_accounting", "checkpoint_state_digests",
        "artifact_bindings", "stage_execution", "scientific_decision",
        "scientific_component_payloads",
        "scientific_counters", "frozen_before_independent_validation",
        "immutable_after_freeze", "presentation_fields_present",
        "failed_output_files_reused", "content_digest",
    )):
        raise V2ContractError("immutable scientific payload schema drift")
    if (
        value["schema"] != IMMUTABLE_SCIENTIFIC_PAYLOAD_SCHEMA
        or value["experiment_id"] != EXPERIMENT_ID
        or value["source_experiment_id"] != SOURCE_EXPERIMENT_ID
    ):
        raise V2ContractError("immutable scientific payload identity drift")
    rebuilt = build_immutable_scientific_payload(
        attempt_id=value["attempt_id"],
        source_freeze_commit=value["source_freeze_commit"],
        scientific_invariance_receipt=value["scientific_invariance_receipt"],
        namespace_and_nonreuse_receipt=value[
            "namespace_and_nonreuse_receipt"
        ],
        artifact_bindings=value["artifact_bindings"],
        checkpoint_state_digests=value["checkpoint_state_digests"],
        scientific_decision=value["scientific_decision"],
        scientific_counters=value["scientific_counters"],
        scientific_component_payloads=value[
            "scientific_component_payloads"
        ],
    )
    if value != rebuilt:
        raise V2ContractError("immutable scientific payload drift")
    return copy.deepcopy(value)


def immutable_scientific_payload_bytes(value: Mapping[str, Any]) -> bytes:
    validate_immutable_scientific_payload(value)
    return canonical_json_bytes(value) + b"\n"


def _artifact_binding_occurrences(
    value: Any, *, locator: str = "$"
) -> list[tuple[str, dict[str, Any]]]:
    if _has_exact_keys(value, ARTIFACT_BINDING_FIELDS):
        return [(locator, validate_artifact_binding(value))]
    rows: list[tuple[str, dict[str, Any]]] = []
    if type(value) is dict:
        for key, item in value.items():
            rows.extend(
                _artifact_binding_occurrences(
                    item, locator=f"{locator}.{key}"
                )
            )
    elif type(value) is list:
        for index, item in enumerate(value):
            rows.extend(
                _artifact_binding_occurrences(
                    item, locator=f"{locator}[{index}]"
                )
            )
    return rows


def phase2_artifact_rehash_authority_rows(
    immutable_payload: Mapping[str, Any],
) -> list[dict[str, Any]]:
    """Flatten every unique top-level or nested scientific file binding."""

    payload = validate_immutable_scientific_payload(immutable_payload)
    grouped: dict[str, dict[str, Any]] = {}
    locators: dict[str, list[str]] = {}
    for locator, binding in _artifact_binding_occurrences(payload):
        path = binding["path"]
        if path in grouped and grouped[path] != binding:
            raise V2ContractError("conflicting nested artifact binding")
        grouped[path] = binding
        locators.setdefault(path, []).append(locator)
    return [
        {
            "sequence": sequence,
            "path": path,
            "path_kind": (
                "ABSOLUTE_FROZEN_RUNTIME_DEPENDENCY"
                if Path(path).is_absolute()
                else "ATTEMPT_ROOT_RELATIVE"
            ),
            "occurrence_locators": sorted(locators[path]),
            "expected_binding": grouped[path],
        }
        for sequence, path in enumerate(sorted(grouped), 1)
    ]


def _logical_rows_from_observed_artifact(
    *, path: str, payload: bytes, expected_rows: int | None
) -> int | None:
    if expected_rows is None:
        return None
    if path.endswith(".jsonl"):
        lines = payload.splitlines()
        if not lines or payload != b"\n".join(lines) + b"\n":
            raise V2ContractError("rehash JSONL canonical bytes drift")
        try:
            documents = [json.loads(line.decode("utf-8")) for line in lines]
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise V2ContractError("rehash JSONL row decode failed") from exc
        if any(type(row) is not dict for row in documents):
            raise V2ContractError("rehash JSONL row type drift")
        observed = len(documents)
    else:
        try:
            document = json.loads(payload.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise V2ContractError("row-counted JSON artifact decode failed") from exc
        if type(document) is not dict:
            raise V2ContractError("row-counted JSON artifact type drift")
        candidates: list[int] = []
        for key in (
            "row_count", "record_count", "prediction_tensor_files",
            "state_records", "logical_records", "donor_mapping_rows",
        ):
            item = document.get(key)
            if type(item) is int:
                candidates.append(item)
        for key in (
            "rows", "records", "worker_exit_custodies",
            "state_records", "logical_records",
        ):
            item = document.get(key)
            if type(item) is list:
                candidates.append(len(item))
        if expected_rows not in candidates:
            raise V2ContractError("row-counted JSON logical rows drift")
        observed = expected_rows
    if observed != expected_rows:
        raise V2ContractError("artifact rehash row count drift")
    return observed


def _observe_bound_artifact_no_follow(
    *, root_fd: int, authority: Mapping[str, Any]
) -> dict[str, Any]:
    expected = validate_artifact_binding(authority["expected_binding"])
    path = expected["path"]
    absolute = authority["path_kind"] == "ABSOLUTE_FROZEN_RUNTIME_DEPENDENCY"
    parent_fd = -1
    file_fd = -1
    try:
        if absolute:
            absolute_path = Path(path)
            parent_fd, components = (
                _open_absolute_directory_componentwise_no_follow(
                    absolute_path.parent
                )
            )
            leaf = absolute_path.name
        else:
            parent_fd, leaf = _open_v2_runtime_parent_directory(
                root_fd, path, create=False
            )
            components = None
        before = os.stat(leaf, dir_fd=parent_fd, follow_symlinks=False)
        file_fd = _v2_os_open(
            leaf,
            os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW,
            dir_fd=parent_fd,
        )
        opened = os.fstat(file_fd)
        if (
            not stat.S_ISREG(opened.st_mode)
            or opened.st_nlink != 1
            or _extended_stat_row(before) != _extended_stat_row(opened)
            or (
                not absolute
                and (
                    stat.S_IMODE(opened.st_mode) != RUNTIME_FILE_MODE
                    or opened.st_uid != os.getuid()
                    or opened.st_gid != os.getgid()
                )
            )
        ):
            raise V2ContractError("artifact rehash open custody drift")
        chunks: list[bytes] = []
        digest = hashlib.sha256()
        total = 0
        while True:
            chunk = os.read(file_fd, 1024 * 1024)
            if not chunk:
                break
            chunks.append(chunk)
            digest.update(chunk)
            total += len(chunk)
        after = os.fstat(file_fd)
        path_after = os.stat(
            leaf, dir_fd=parent_fd, follow_symlinks=False
        )
        payload = b"".join(chunks)
        if (
            _extended_stat_row(opened) != _extended_stat_row(after)
            or _extended_stat_row(after) != _extended_stat_row(path_after)
            or digest.hexdigest() != expected["sha256"]
            or total != expected["bytes"]
        ):
            raise V2ContractError("artifact rehash bytes drift")
        observed_content_digest = None
        if expected["content_digest"] is not None:
            try:
                document = json.loads(payload.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise V2ContractError(
                    "content-digested artifact is not JSON"
                ) from exc
            if type(document) is not dict:
                raise V2ContractError("content-digested artifact type drift")
            observed_content_digest = document.get("content_digest")
            if observed_content_digest != expected["content_digest"]:
                raise V2ContractError("artifact content digest drift")
        rows = _logical_rows_from_observed_artifact(
            path=path, payload=payload, expected_rows=expected["rows"]
        )
        observed_binding = build_artifact_binding(
            path=path,
            sha256=digest.hexdigest(),
            bytes_count=total,
            content_digest=observed_content_digest,
            rows=rows,
        )
        if observed_binding != expected:
            raise V2ContractError("artifact rehash binding drift")
        if not absolute:
            _reverify_v2_runtime_parent_directory(
                root_fd=root_fd,
                relative_path=path,
                opened_parent_fd=parent_fd,
            )
        return {
            **copy.deepcopy(dict(authority)),
            "parent_component_rows": components,
            "stat_before_open_after": _extended_stat_row(opened),
            "observed_binding": observed_binding,
            "all_path_components_opened_no_follow": True,
            "leaf_content_opened_and_rehashed": True,
        }
    finally:
        if file_fd >= 0:
            os.close(file_fd)
        if parent_fd >= 0:
            os.close(parent_fd)


def observe_phase2_artifact_rehash_receipt(
    *,
    immutable_payload: Mapping[str, Any],
    validator_process_identity: Mapping[str, Any],
    reopened_attempt_root_fd_custody: Mapping[str, Any],
    parent_fd: int,
    root_fd: int,
) -> dict[str, Any]:
    payload = validate_immutable_scientific_payload(immutable_payload)
    validator = _require_exact_live_process_identity(
        validator_process_identity
    )
    historical = payload["scientific_component_payloads"]["values"][
        "attempt_root_fd_custody"
    ]
    reopened = validate_reopened_attempt_root_fd_custody(
        reopened_attempt_root_fd_custody,
        attempt_root_fd_custody=historical,
        parent_fd=parent_fd,
        root_fd=root_fd,
        reverify_live=True,
    )
    if (
        reopened["phase_id"] != PHASE_IDS[1]
        or reopened["phase_process_identity"] != validator
    ):
        raise V2ContractError("Phase-2 artifact rehash root drift")
    started = time.monotonic_ns()
    authority = phase2_artifact_rehash_authority_rows(payload)
    rows = [
        _observe_bound_artifact_no_follow(root_fd=root_fd, authority=row)
        for row in authority
    ]
    ended = time.monotonic_ns()
    return attach_self_digest(
        {
            "schema": PHASE2_ARTIFACT_REHASH_RECEIPT_SCHEMA,
            "experiment_id": EXPERIMENT_ID,
            "attempt_id": payload["attempt_id"],
            "validator_process_identity": validator,
            "reopened_attempt_root_fd_custody": reopened,
            "authority_rows": authority,
            "artifact_rehash_rows": rows,
            "artifact_bindings_rehashed": len(rows),
            "artifact_bound_bytes_rehashed": sum(
                row["observed_binding"]["bytes"] for row in rows
            ),
            "started_monotonic_ns": started,
            "ended_monotonic_ns": ended,
            "failed_output_files_opened": 0,
            "correction_replay_receipts_opened": 0,
            "all_paths_opened_componentwise_no_follow": True,
            "pass": True,
        }
    )


def validate_phase2_artifact_rehash_receipt(
    value: Mapping[str, Any], *, immutable_payload: Mapping[str, Any]
) -> dict[str, Any]:
    validate_self_digest(value)
    payload = validate_immutable_scientific_payload(immutable_payload)
    required = (
        "schema", "experiment_id", "attempt_id",
        "validator_process_identity",
        "reopened_attempt_root_fd_custody", "authority_rows",
        "artifact_rehash_rows", "artifact_bindings_rehashed",
        "artifact_bound_bytes_rehashed", "started_monotonic_ns",
        "ended_monotonic_ns", "failed_output_files_opened",
        "correction_replay_receipts_opened",
        "all_paths_opened_componentwise_no_follow", "pass",
        "content_digest",
    )
    if not _has_exact_keys(value, required) or (
        value["schema"] != PHASE2_ARTIFACT_REHASH_RECEIPT_SCHEMA
        or value["experiment_id"] != EXPERIMENT_ID
        or value["attempt_id"] != payload["attempt_id"]
        or value["authority_rows"]
        != phase2_artifact_rehash_authority_rows(payload)
        or type(value["started_monotonic_ns"]) is not int
        or type(value["ended_monotonic_ns"]) is not int
        or value["started_monotonic_ns"] < 0
        or value["ended_monotonic_ns"] < value["started_monotonic_ns"]
        or value["failed_output_files_opened"] != 0
        or value["correction_replay_receipts_opened"] != 0
        or value["all_paths_opened_componentwise_no_follow"] is not True
        or value["pass"] is not True
    ):
        raise V2ContractError("Phase-2 artifact rehash receipt drift")
    validator = _validate_process_identity(value["validator_process_identity"])
    historical = payload["scientific_component_payloads"]["values"][
        "attempt_root_fd_custody"
    ]
    reopened = validate_reopened_attempt_root_fd_custody(
        value["reopened_attempt_root_fd_custody"],
        attempt_root_fd_custody=historical,
        reverify_live=False,
    )
    if (
        reopened["phase_id"] != PHASE_IDS[1]
        or reopened["phase_process_identity"] != validator
    ):
        raise V2ContractError("Phase-2 rehash process/root drift")
    rows = value["artifact_rehash_rows"]
    authority = value["authority_rows"]
    if type(rows) is not list or len(rows) != len(authority):
        raise V2ContractError("Phase-2 artifact rehash row count drift")
    for expected, row in zip(authority, rows):
        if not _has_exact_keys(row, (
            "sequence", "path", "path_kind", "occurrence_locators",
            "expected_binding", "parent_component_rows",
            "stat_before_open_after", "observed_binding",
            "all_path_components_opened_no_follow",
            "leaf_content_opened_and_rehashed",
        )):
            raise V2ContractError("Phase-2 artifact rehash row schema drift")
        if (
            {key: row[key] for key in expected} != expected
            or row["observed_binding"] != expected["expected_binding"]
            or row["all_path_components_opened_no_follow"] is not True
            or row["leaf_content_opened_and_rehashed"] is not True
        ):
            raise V2ContractError("Phase-2 artifact rehash row value drift")
        _validate_extended_stat_row(
            row["stat_before_open_after"],
            expected_file_type="REGULAR_FILE", expected_nlink=1,
        )
        components = row["parent_component_rows"]
        if expected["path_kind"] == "ATTEMPT_ROOT_RELATIVE":
            if components is not None:
                raise V2ContractError("attempt artifact has absolute components")
        elif type(components) is not list or not components:
            raise V2ContractError("absolute artifact lacks component custody")
    if (
        value["artifact_bindings_rehashed"] != len(rows)
        or value["artifact_bound_bytes_rehashed"]
        != sum(row["observed_binding"]["bytes"] for row in rows)
    ):
        raise V2ContractError("Phase-2 artifact rehash totals drift")
    return copy.deepcopy(value)


